(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["ja"] = {"ui":{"lead":"人びとはゲームを遊ぶだけでなく、描いてきました。3300年分の絵と像を、拡大して細かいところまで見てみましょう。","details":"見どころ","links":"このゲームを見る・遊ぶ","record":"作品の記録","game":"ゲーム","exhibit":"所蔵品","room":"展示室","room_chance":"偶然の道具","hint":"ピンチ・ホイールで拡大 · ドラッグで移動 · 番号をタップ","r_artist":"作者","r_date":"年代","r_place":"地域","r_medium":"材質・技法","r_size":"大きさ","r_museum":"所蔵","r_credit":"受け入れ","r_rights":"画像","met":"メトロポリタン美術館","cc0":"オープンアクセス（パブリックドメイン）","metlink":"美術館の作品ページ","credit":"画像はメトロポリタン美術館・クリーブランド美術館・シカゴ美術館・アムステルダム国立美術館のオープンアクセス（パブリックドメイン）によります。","cma":"クリーブランド美術館","aic":"シカゴ美術館","rijks":"アムステルダム国立美術館"},"ex":{},"nefertari":{"title":"セネトを打つネフェルタリ王妃","artist":"ニーナ・デ・ガリス・デイヴィス（模写）","date":"原画 紀元前1290〜1224年頃・模写 1921〜22年","place":"エジプト（王妃の谷）","game":"セネト","medium":"紙にテンペラ（原寸の1/2の模写）","size":"43×46cm","credit":"ロジャーズ基金、1930年","p":["ネフェルタリはラムセス2世の第一王妃。王妃の谷にある彼女の墓の壁画を、1921〜22年に墓の中で写したものです。原画のひび割れや欠けまで、そのまま写されています。","王妃は盤の前に座り、見えない相手とセネトを打っています。墓に描かれたセネトは、ただの遊びではなく、あの世への旅を勝ち抜くという意味をもっていたと考えられています。"],"spots":[["2種類の駒","盤の上には、とがった頭の駒と糸巻き形の駒が並びます。対局する2人の駒です。"],["王妃の手","駒をつまもうとする指先。"],["盤と台","盤は横から描かれているので、マスは見えません。細い脚の台に載っています。"],["名前の枠","楕円の枠（カルトゥーシュ）の中に、王妃の名が書かれています。"],["見えない相手","向かい側には誰もいません。王妃は見えない相手と対局しています。"]]},"hydria":{"title":"ゲームに興じるアキレウスとアイアス（水がめ）","artist":"レアグロス・グループ（に帰属）","date":"紀元前510年頃","place":"ギリシア（アッティカ）","game":"さいころのゲーム","medium":"テラコッタ（黒像式）","size":"高さ54.1cm","credit":"フレッチャー基金、1956年","p":["トロイア戦争の陣中で、ギリシアの2人の英雄アキレウスとアイアスが盤を囲んで時間をつぶしている場面です。紀元前540年頃に陶工・画家のエクセキアスが描き出した図柄で、その原作はヴァチカン美術館のアンフォラに残っています。","この主題は紀元前540〜480年頃にとても好まれ、150例以上が知られています。この水がめでは、まん中に女神アテナが立っています。2人が遊んでいるのは、さいころを振って駒を進めるゲームです。"],"spots":[["女神アテナ","女神アテナが、2人のあいだに立っています。"],["左の英雄","槍を持ったまま、身をかがめて盤をのぞきこみます。"],["右の英雄","こちらも武器を手放していません。戦いのさなかの、つかのまの遊びです。"],["盤","2人のあいだの低い台が盤です。"],["肩の絵","かめの肩には、出発する戦車が描かれています。"]]},"liubo":{"title":"六博を打つ2人（副葬の像）","artist":"","date":"紀元前1世紀〜紀元1世紀","place":"中国（漢）","game":"六博","medium":"彩色した土器","size":"高さ35.1cm・34.6cm","credit":"チャールズ＆ジョン・ウェーバー夫妻寄贈、1992年","p":["漢の時代に大流行した六博を打つ2人の像です。墓に納められ、死後の暮らしでも楽しみが続くようにという願いがこめられています。","写真では、2人のあいだに、この博物館の所蔵品でもある六博の盤と骨の駒が置かれています。白熱した一局の、劇的な瞬間をとらえた像です。"],"spots":[["六博の盤","この博物館の所蔵品「六博の盤と駒」と同じ盤です。T・L・Vの印が見えます。"],["左の打ち手","落ち着いて盤を見つめています。"],["右の打ち手","片手を上げ、口を大きく開けています。いい手が決まったのでしょうか。"],["盤上の駒","骨の駒が、盤の両端に並んでいます。"],["盤の外の駒","床にも駒が置かれています。"]]},"shahnama":{"title":"ブズルジミフル、インドのゲーム「チェス」を解く（『シャー・タフマースブの王書』より）","artist":"アブドゥルワッハーブ（に帰属）","date":"1530〜35年頃","place":"イラン（タブリーズ）","game":"チェス","medium":"紙に不透明水彩・インク・銀・金","size":"絵 24.4×17.5cm（ページ 47.3×31.8cm）","credit":"アーサー・A・ホートン・ジュニア寄贈、1970年","p":["フィルドウスィーの叙事詩『王書（シャーナーメ）』の一場面です。インドの王が使者にチェスの盤と駒を持たせ、ペルシアの王ヌーシルヴァーンに「遊び方を解いてみせよ。解ければ貢ぎ物を払おう」と挑みます。","時間内に解き明かしたのは、若い賢者ブズルジミフルだけでした。王書では、ペルシアはお返しにバックギャモンを送り、インドは解けなかったと語られます。王と廷臣たちが、盤と打ち手を食い入るように見つめています。"],"spots":[["チェス盤","格子の盤の上に駒が並びます。細かくて形まではわかりにくいほどです。"],["王ヌーシルヴァーン","玉座に座り、謎解きの行方を見守ります。"],["盤を囲む人びと","身を乗り出して盤をのぞきこむ打ち手たち。"],["詩の文字","上と下の枠には、フィルドウスィーの詩が書かれています。"],["廷臣たち","赤い棒の立つターバンの人びとが、立って見物しています。"]]},"chaupar":{"title":"チャウパルを打つシヴァとパールヴァティー（『ラサマンジャリー』の一葉）","artist":"ヌールプルのデーヴィーダーサ","date":"1694〜95年","place":"インド（バソーリー、ジャンムー）","game":"チャウパル（ルドーの祖先の仲間）","medium":"紙に不透明水彩・インク・銀・金","size":"絵 16.5×27.6cm","credit":"J・C・バーネット博士寄贈、1957年","p":["15世紀のサンスクリットの恋愛詩『ラサマンジャリー』の連作の一枚です。シヴァ神と妻パールヴァティーが、トラの毛皮の上で十字形の盤を囲んでいます。","シヴァにずるをされて首飾りを取られたパールヴァティーが、返してほしいと訴える場面です。大胆な色と、奥行きのあいまいな空間。色と身ぶりに意味をこめるのが、バソーリー派の持ち味です。"],"spots":[["十字形の盤","チャウパルやパチーシの盤は、このような十字の形をしています。"],["盤の上の白い棒","チャウパルで振る細長いさいころ（パーサ）と思われます。"],["シヴァ","白い体に、首にはヘビ。"],["パールヴァティー","手を差し出して、首飾りを返してと訴えています。"],["トラの毛皮","2人はトラの毛皮の上に座っています。"]]},"shogi":{"title":"将棋をさす若い男女（「中納言兼輔」・三十六歌仙見立て）","artist":"鈴木春信","date":"1767〜69年頃","place":"日本（江戸）","game":"将棋","medium":"木版画（錦絵）","size":"28.3×20.6cm","credit":"ヘンリー・L・フィリップス・コレクション、1939年","p":["三十六歌仙になぞらえた連作の一枚で、この絵は中納言兼輔に見立てられています。夏の夜、蚊帳のそばで若い男女が将棋盤を囲んでいます。","春信は、多くの色を重ねて摺る錦絵を広めた絵師です。盤の上の駒の並びまで、細かく描かれています。"],"spots":[["脚のついた将棋盤","いまと同じ、脚つきの厚い盤です。"],["小箱","駒をしまう箱と思われます。"],["蚊帳","緑の蚊帳がつられています。夏の夜の場面です。"],["行灯","盤を照らす明かり。"],["歌の札","雲の形の枠に、歌仙の名と歌が書かれています。"]]},"sugoroku":{"title":"双六を打つ2人の娘","artist":"初代 歌川豊国","date":"江戸時代（18世紀末〜19世紀初め）","place":"日本（江戸）","game":"盤双六（バックギャモンの仲間）","medium":"木版画（二枚続き）","size":"各 38.1×25.6cm","credit":"H・O・ハヴマイヤー・コレクション、J・ワトソン・ウェブ夫人寄贈、1930年","p":["2枚の版画をつなげた大きな画面で、座敷に集まった娘たちが盤双六を楽しんでいます。盤双六は、正倉院の木画紫檀双六局と同じ流れをくむ、バックギャモンの仲間です。","盤には白と黒の石が並び、右の娘は筒（さいころを振る入れ物）を手にしています。窓の外には富士山が見えます。"],"spots":[["双六盤","細長いマスに、白と黒の石が並びます。"],["さいころの筒","筒にさいころを入れて振ります。"],["盤の外の石","上がった石や、まだ盤に出ていない石でしょうか。"],["富士山","窓の向こうに、富士の姿。"],["2枚のつなぎ目","ここで2枚の版画がつながっています。"]]},"eakins":{"title":"チェスをする人びと","artist":"トマス・イーキンズ","date":"1876年","place":"アメリカ（フィラデルフィア）","game":"チェス","medium":"板に油彩","size":"29.8×42.6cm","credit":"作者寄贈、1881年","p":["フィラデルフィアの家の客間で、2人の友人がチェスを指し、作者の父ベンジャミン・イーキンズがそれを見ています。作者は、ていねいな空間の組み立てと細部の描写を、パリで師事したジェロームから学びました。","1881年、この絵は、存命の画家からの寄贈としてメトロポリタン美術館が初めて受け入れた作品になりました。"],"spots":[["チェスの駒","薄暗い部屋の中で、盤の駒が明るく浮かび上がります。"],["作者の父","立って勝負を見守るのは、作者の父ベンジャミン。"],["右の打ち手","画家ジョージ・W・ホームズ。作者の父の友人です。"],["机の引き出し","「ベンジャミン・イーキンズの息子が76年に描いた」という意味のラテン語が書かれています。"],["暖炉の上の絵","師ジェロームの絵の複製がかかっています。"],["猫","床の上で、猫だけは勝負に興味がなさそうです。"]]},"weiqi":{"title":"碁を打つ仙人の皿","artist":"作者不明","date":"1425〜36年（明・宣徳年間）","place":"中国","game":"囲碁（ウェイチー）","medium":"彫漆（朱と緑の漆を塗り重ねて彫る）","size":"高さ3.5・幅14.9・長さ23.5cm","credit":"フローレンス＆ハーバート・アーヴィング寄贈、2015年","p":["漆を何十層も塗り重ねてから彫り出す「彫漆」の皿です。赤い漆の下に緑の漆の層があり、彫りの深さで色を出し分けています。花の形の縁の内側に、松の下で碁を打つ仙人たちが表されています。","中国には、山で仙人の碁を見ていた木こりの王質が、ふと気づくと斧の柄が腐るほどの時が過ぎていたという「爛柯（らんか）」の伝説があり、碁を打つ仙人は好まれた題材でした。右に立つ人物が誰なのかは、記録にはありません。"],"spots":[["碁盤","2人の仙人のあいだに置かれた碁盤。線まで細かく彫られています。"],["碁を打つ仙人","岩のそばに座って盤を囲む2人。"],["立って見る人","少し離れて立つ人物。爛柯の伝説の木こりを思わせますが、誰かは分かりません。"],["月","空に浮かぶ丸い月（太陽かもしれません）。"],["松","枝を大きく広げた松。長寿や仙境を表すことの多い木です。"],["牡丹の縁","縁には大きな牡丹の花と葉が彫られています。"]]},"webb":{"title":"バックギャモンをする2人（飾り棚）","artist":"フィリップ・ウェッブ（設計）、エドワード・バーン＝ジョーンズ（絵）、モリス・マーシャル・フォークナー商会（製作）","date":"1861年","place":"イギリス（ロンドン）","game":"バックギャモン","medium":"彩色した松材、革に油彩、真鍮、銅","size":"高さ185.4・幅114.3・奥行き53.3cm","credit":"ロジャーズ基金、1926年","p":["ウィリアム・モリスが仲間と1861年に始めた会社の、最初期の家具です。扉の革の上に、中世風の服を着た男女がバックギャモンに向かう姿が油絵で描かれています。翌1862年のロンドン国際博覧会にも出品されました。","「美術」と「工芸」の境をなくそうとしたアーツ・アンド・クラフツ運動の考えをよく表す作品です。革に細かな点を打ち出した背景は、中世の技法にならったものです。"],"spots":[["盤","2人のあいだのテーブルに置かれたバックギャモンの盤。"],["男","駒を手に、盤をじっと見つめる若い男。"],["女","向かいに座る女。手に駒（またはさいころ入れ）を持っています。"],["足もとの花","2人の足もとには花が咲いています。"],["打ち出した革","背景の革には細かな点が打ち出され、光を受けてきらめきます。"],["ひし形の帯","扉の上下を、金地にひし形の模様が囲みます。"]]},"liberale":{"title":"チェスをする人々","artist":"リベラーレ・ダ・ヴェローナ","date":"1475年ごろ","place":"イタリア（ヴェローナ）","game":"チェス","medium":"板にテンペラ","size":"34.9×41.3cm","credit":"メイトランド・F・グリッグス遺贈、1943年","p":["ルネサンスのイタリアで、花嫁道具を入れる飾り箱「カッソーネ」の正面を飾っていた板絵の断片です。作者のリベラーレは、シエナ大聖堂の聖歌集の挿絵でも知られる画家です。","描かれているのは、名前の分からない恋物語の一場面。もう一枚の断片では、窓辺の娘が若者を招き入れるように見え、この絵では2人がチェスを指しています。美術館の解説によれば、勝負は娘の負けが近いところ。チェスは当時の恋の文学でよく使われた、駆け引きの象徴でした。"],"spots":[["チェス盤","赤と白の市松の盤。黒い駒が並び、勝負は終盤に入っているようです。"],["若者","盤に手をのばす若者。この勝負は彼が勝ちそうです。"],["娘","向かいに座る娘。もう一枚の断片では窓から若者を招いていました。"],["窓の外","開いた窓の向こうに丘と空が見えます。"],["見物する若者たち","腕を組んで勝負を見守る男たち。"],["見物する娘たち","柱の向こうから勝負をのぞく娘たち。"]]},"mirror":{"title":"チェスをする恋人たちの鏡箱","artist":"作者不明","date":"1325〜50年","place":"フランス（パリ）","game":"チェス","medium":"象牙","size":"直径10.2cm","credit":"J・H・ウェイド基金による購入、1940年","p":["手のひらほどの象牙の円板は、手鏡のふたでした。14世紀のパリでは、磨いた金属の鏡を2枚の象牙の板ではさみ、持ち歩きました。こうした象牙細工は、宮廷や貴族が好んだぜいたく品です。","幕を張ったテントの中で、若者と婦人がチェスを指しています。中世の物語では、チェスは恋と戦いの両方をあらわしました。2人はトリスタンとイゾルデ、あるいはランスロットとグィネヴィアだという説もありますが、確かなことはわかりません。美術館の問いかけは「どちらが勝っていると思いますか？」。"],"spots":[["チェス盤","1本脚の台にのった盤。駒がいくつか立っています。"],["若者","盤に手をのばして、次の一手を指そうとしています。"],["婦人","頭巾をかぶった婦人。指先が盤の駒にふれています。"],["握った手","もう一方の手は握って膝の上に。取った駒を握っているのでしょうか。"],["テントの幕","両側に結んだ幕。チェスの場面を彫った鏡箱にはよく見られる舞台です。"]]},"morris":{"title":"ミューレ（ナイン・メンズ・モリス）の盤","artist":"ペーター・フレットナー","date":"1500〜46年","place":"ドイツ","game":"ナイン・メンズ・モリス","medium":"木版画","credit":"チャールズ・W・ハークネス基金、1923年","p":["ルネサンスのニュルンベルクで活躍した彫刻家ペーター・フレットナーの木版画です。フレットナーは装飾の図案や家具、金細工の原型、風刺のきいたトランプのデザインでも知られます。渦巻く唐草の下に隠れているのは、ドイツで「ミューレ」と呼ばれるナイン・メンズ・モリスの盤。三重の正方形を、辺のまん中で結んだ形です。","盤の交点は24か所。駒を3つ一列にそろえる（ミル）と、相手の駒を1つ取れます。こうした版画は職人の手本にもなり、美術館はこの1枚を金細工師の原型と図案の展覧会に出しました。紙のまま遊ばれたのか、木や金属に写されたのかは記録に残っていません。"],"spots":[["中心の正方形","いちばん内側の正方形。細かな唐草で埋めつくされています。"],["外側の角","外側の正方形の角。駒を置く24の点のひとつです。"],["中ほどの角","まん中の正方形の角も、駒を置く点です。"],["つなぐ線","3つの正方形を辺のまん中で結ぶ帯。駒はこの上も動きます。"],["仮面","上下左右には、渦巻く飾り枠と顔の飾り。ルネサンスらしいグロテスク装飾です。"],["ぶどうの縁取り","葉と実の唐草が、黒地に白く彫り出されています。"]]},"leifeng":{"title":"雷峰塔のすごろく","artist":"作者不明","date":"1736〜95年（乾隆年間）","place":"中国","game":"すごろく（盤上の競走）","medium":"木版画、紙に墨","size":"31×29.8cm","credit":"J・H・ウェイド基金による購入、2025年","p":["清の乾隆帝の時代に刷られた、遊ぶための一枚刷りです。マスに描かれているのは中国の民話『白蛇伝』の人びと。白蛇の精の白娘子（白娘）、その連れの小青、若者の許宣（のちの版では許仙）、そして最後に白娘子を西湖のほとりの雷峰塔の下に封じこめる僧・法海です。","道は「起馬」と書かれたマスから渦を巻いて中心の塔へ向かいます。西洋のガチョウのゲームのように、さいころで物語をたどって競ったのでしょう。遊び方の記録は残っていません。美術館によれば、こうした色刷りの一枚物は都市で売られ、壁に飾られる町の文化になっていきました。色ごとに別の版木を彫って刷っています。"],"spots":[["起馬","「起馬」と書かれたマス。ここがふりだしと思われます。"],["白娘と小青","白蛇の精・白娘子と、その連れの小青。"],["許宣","白娘子と結ばれる若者。"],["法海禅師","白娘子を塔に封じる僧。"],["雷峰塔","杭州・西湖の雷峰塔。物語のしめくくりの舞台です。"],["中心","塔の前に座る女性と、ひざまずく男性。物語の結末の場面で、ここがあがりでしょうか。"]]},"tutinama":{"title":"チェス仲間の王子の手をかむ猿（『トゥーティー・ナーマ（オウムの物語）』より）","artist":"ダサヴァンタ","date":"1560年ごろ","place":"インド（アクバルのムガル宮廷）","game":"チェス","medium":"紙に不透明水彩・墨・金","size":"20×14.2cm（絵の部分 10.2×10.6cm）","credit":"A・ディーン・ペリー夫人寄贈、1962年","p":["ムガル帝国のアクバル帝の宮廷で作られた物語集『トゥーティー・ナーマ（オウムの物語）』の挿絵です。母オウムが子どもたちに、狐の子のような違う種類の生き物と仲よくしてはいけないと教えるために語る話のひとつ。チェスが上手な猿が、王子といつもチェスを指していました。","ある日、王子が客を招いた席で猿が失礼な冗談を言い、王子に平手打ちされます。怒った猿は王子の手にかみつきました。右の外では召使いが料理の支度をし、客たちは驚いて見ています。下の書き込みには、のちにムガル宮廷で最も名高い画家の一人になるダサヴァンタの名があります。若い彼は、絵の下に涼しい青の色を一層塗っていたそうです。"],"spots":[["猿","王子の手にかみつく猿。王子のチェス仲間でした。"],["王子","手をかまれた王子。"],["チェス盤","赤い升目の盤が床に置かれています。"],["驚く客たち","宴に招かれた客たち。"],["料理の支度","外で鍋を火にかける召使いたち。"],["ペルシア語の本文","上の枠には物語の文がペルシア語で書かれています。"]]},"teniers":{"title":"バックギャモンの勝負","artist":"ダーフィット・テニールス","date":"1640年代","place":"フランドル","game":"バックギャモン","medium":"油彩、板から画布に移し替え","size":"59×80.6cm","credit":"サミュエル・D・ワイズ夫妻寄贈、1943年","p":["フランドルの画家テニールスが描いた、賭けのかかったバックギャモンの大勝負です。バックギャモンの歴史は長く、いまの形は1400年代に現れ、「バックギャモン」という名前はちょうどこの絵のころに生まれたといいます。1600年代にはとても流行し、お金を賭けてよく遊ばれました。","2人の対局者のまわりには見物人がいて、壁ぎわでは点数をつけている人もいます。窓から見下ろす女性などから、美術館はここを娼館の遊技部屋とみています。こうした遊びの場面は、賭けごとは愚かで悪いこと、時間のむだだという教えを込めて描かれることがよくありました。"],"spots":[["盤","開いたバックギャモン盤。手前のテーブルの上で勝負が進んでいます。"],["白いシャツの男","背中を見せる対局者。駒に手をのばしています。"],["頬づえの男","向かいの対局者。頬に手を当てて考えこんでいます。"],["点数をつける人","壁ぎわで板に印をつけている男。点数か賭け金の記録でしょうか。"],["窓の女性","窓から勝負をのぞく年配の女性。"],["奥の部屋","奥では女性のそばで男たちが飲んでいます。"]]},"imari":{"title":"碁を打つ2人の角皿","artist":"作者不明","date":"1700年代","place":"日本（江戸時代）","game":"囲碁","medium":"磁器、型打ち、上絵付（肥前、伊万里様式）","size":"2.4×13.8cm","credit":"セヴェランス・アンド・グレタ・ミリキン・コレクション、1964年","p":["手のひらにのる小さな角皿に、松の木の下で碁を打つ2人が描かれています。地面にじかに置いた盤を、黄色い衣の人と、木にもたれた緑の衣の人がはさんでいます。","肥前（いまの佐賀・長崎）で焼かれた伊万里の磁器で、緑の色づかいは九谷の色絵に通じるといいます。日本が中国に代わってヨーロッパへの輸出磁器のおもな作り手になったころ、輸出向けに作られた品です。"],"spots":[["碁盤","升目を描いた碁盤。地面に直接置かれています。"],["黄色い衣の人","盤に向かって座る人。"],["緑の衣の人","木にもたれて笑う相手。"],["松","頭上に枝をのばす松。"],["赤い枠","角を切った赤い枠が絵を囲みます。"]]},"shoei":{"title":"琴棋書画図屛風（一隻）","artist":"伝 狩野松栄","date":"1500年代末〜1600年代初め","place":"日本（桃山時代）","game":"囲碁","medium":"六曲一双のうち一隻、紙本墨画淡彩","size":"153×358.6cm","credit":"ジョン・L・セヴェランス基金、1979年","p":["狩野派の画家・狩野松栄の作と伝わる六曲屛風です。中国の文人が身につけるべきたしなみとされた「琴棋書画」——琴をひき、碁（棋）を打ち、書を書き、絵を描くこと——を、二隻一組で描いたうちの一隻。松の下の野原で、身分の高い中国の紳士たちが従者を連れてくつろいでいます。","まん中では2人が碁を打ち、もう1人がそれを見守っています。そばの机には本と、布の袋に入ったままの琴が置かれ、ひかれるのを待っています。楽しみと礼儀正しさが釣り合った場面です。美術館の解説によれば、従者のひとりは水の中の魚の動きに気を取られているそうです。"],"spots":[["碁盤","脚のついた碁盤。2人の紳士が向かい合って打っています。"],["紳士たち","碁を打つ2人と、それを見守るもう1人。"],["机の上","本と、袋に入ったままの琴が置かれた机と思われます。"],["従者たち","机のそばに控える従者。"],["魚に気を取られる従者","水辺に寝そべり、魚の動きを見ている従者。"],["松","画面の上に大きく枝を広げる松。"]]},"umaya":{"title":"厩図屏風（碁と将棋の縁側）","artist":"作者不明","date":"1500年代前半","place":"日本（室町時代）","game":"囲碁・将棋","medium":"六曲一双のうち一隻。紙本着色・金","size":"146.1×346.6cm","credit":"エドワード・L・ウィッテモア基金による購入、1934年","p":["6枚のパネルをつないだ屏風で、左右2つで一組になるうちの片方です。厩につながれた自慢の馬たちがおもな主題ですが、手前の縁側でも、にぎやかなことが起きています。","縁側では人びとが2つのゲームで勝負しています。左は碁、右は将棋。美術館の解説によれば、暴れる馬たちと、じっと考える盤上の勝負とのかけあいが、場をいきいきとさせています。日本では猿が馬の守り神とされ、厩で猿を飼うこともありました。"],"spots":[["碁盤","細かい升目に黒い石が並ぶ碁盤。"],["烏帽子の2人","黒い烏帽子の男たち。緑の衣の男が盤に手をのばし、赤い衣の男がそばで見ています。"],["将棋盤","升目の大きな盤。碁盤とくらべると、升目がずっと少ないのがわかります。"],["笑う相手","坊主頭の僧が駒をつまみ、向かいの男は頭に手をやって大笑い。どちらかが一本取ったのでしょうか。"],["猿","縁側の端に、赤い服を着た猿でしょうか。"],["馬","前脚を上げてはねる黒い馬。綱でつながれています。"]]},"goryeo":{"title":"碁を打つ人の象嵌青磁の水注","artist":"作者不明","date":"1200年代","place":"朝鮮半島（高麗）","game":"囲碁（パドゥク）","medium":"青磁、白土と黒土の象嵌","size":"高さ20.4cm、径14.3cm","credit":"ジョン・L・セヴェランス寄贈、1917年","p":["高麗の青磁の水注（注ぎ口と取っ手のある器）です。器に彫った線に白と黒の土をうめ、釉をかけて焼く「象嵌」は高麗の陶工が得意とした技で、丸い枠の中に、柳の下に座る2人が白く浮かび上がっています。","2人のあいだには盤があり、美術館はこの場面を、碁（韓国語でパドゥク）を打つ姿に通じるものとみています。琴・碁・書・画の「四芸」は文人が身につけるべきたしなみとされ、その優雅な集いは工芸の図柄にもなりました。人物を表した高麗の象嵌青磁はめずらしいものです。"],"spots":[["盤","2人のあいだの盤。白い土で四角く表されています。"],["左の人","盤に向かって座る人。"],["右の人","向かいに座る相手。"],["柳","2人の頭上にたれる柳の枝。黒い土で描かれています。"],["雲の枠","丸い枠のまわりを、渦を巻く雲のような文様がめぐります。"],["貫入","釉の表面の細かなひび（貫入）。焼いたあと冷えるとき、土と釉の縮み方の違いでできます。"]]},"kangra":{"title":"露台でチャウパルをする2人","artist":"作者不明","date":"1790〜1800年ごろ","place":"インド（パハーリー、カングラ派）","game":"チャウパル","medium":"素描、赤土（オーカー）による下描き","size":"19.4×13.2cm","credit":"エドワード・L・ウィッテモア基金による購入、1936年","p":["ヒマラヤのふもとのパハーリー地方、カングラの画家による素描です。赤い線（赤土の顔料）で下描きをし、その上を黒い線で整えています。色が塗られていないので、線の運びや人や道具の形がよくわかります。","露台に座った男女が、十字の形の盤をはさんでチャウパルをしています。チャウパルはパチーシと同じ十字の盤を使う、インドで古くから遊ばれてきた競走のゲームで、長いさいころ（パーサ）を振って駒を進めます。盤にはまだ升目が描かれていません。2人のまわりでは侍女たちが仕えています。"],"spots":[["十字の盤","床に置かれた十字形の盤。升目はまだ描かれていません。"],["女性","手のひらを上に向けた女性。さいころを振ろうとしているのでしょうか。"],["男性","羽根飾りのついたターバンの男性。盤のほうへ手をのばしています。"],["左の侍女","小さなびんを持ち、布をさしかけています。"],["右の侍女","長い柄の道具と小さな器を持っています。"],["赤い下描き","ターバンのまわりに、黒い線の下の赤い下描きが見えます。"]]},"vuillard":{"title":"チェッカーの一局（『風景と室内』より）","artist":"エドゥアール・ヴュイヤール","date":"1899年","place":"フランス","game":"チェッカー","medium":"多色リトグラフ（第3ステート）。刷りはオーギュスト・クロ、版元はアンブロワーズ・ヴォラール","size":"図33×25.7cm（紙38×30.8cm）","credit":"ハンナ基金寄贈、1951年","p":["画商のアンブロワーズ・ヴォラールは、版画の版元でもありました。1895年にボナールに12枚の色刷りリトグラフの画集を頼んだのを手はじめに、次々と画集を出しました。ヴュイヤールの『風景と室内』もそのひとつで、刷ったのは名刷り師オーギュスト・クロです。","ヴュイヤールとボナールは「ナビ派」（ヘブライ語で「預言者」）と呼ばれた画家の仲間で、形と色そのもので気持ちを表す新しい絵をめざし、都会の暮らしや家族の団らんを好んで描きました。模様で埋めつくされた部屋で、男たちがチェッカーの盤をはさみ、女性が立ったまま勝負を見守っています。フランス語でチェッカーは「ダーム」。左下の鉛筆書きは「ダームの一局」と読めます。"],"spots":[["盤","市松の小さな盤。駒が並んでいるのが見えます。"],["左の男","ひげの男が、盤の上に手をのばしています。"],["右の男","向かいの肘掛け椅子で、うつむいて盤を見つめる相手。立っている女性のかげになっています。"],["立つ女性","あごに手を当てて、勝負の行方を見守ります。"],["ランプ","壁ぎわのランプ。壁紙も椅子の布も、模様でいっぱいです。"],["鉛筆の書き込み","左下に鉛筆で「partie de dames（ダームの一局）」と書かれています。"]]},"talbot":{"title":"チェスをする人々（初期の写真）","artist":"ウィリアム・ヘンリー・フォックス・トールボット（とされる）","date":"1843〜47年ごろ","place":"イギリス","game":"チェス","medium":"ソルトプリント（塩化銀紙の写真）","size":"19.9×15cm","credit":"エヴェレット・コヴラー夫妻の資金による購入","p":["トールボットが考え出した「ネガ・ポジ法」は、1枚のネガから何枚でも写真を焼き増せるようにし、デジタルの時代まで写真の基本であり続けました。トールボットの初期の実験には、科学への関心と、芸術への志の両方が表れています。研究によれば、彼はチェスをする人々の写真を10枚以上撮っています。","ただし、この1枚はトールボット本人の作ではないかもしれません。同じ場面の写真には署名がなく、紙もいつもの紙と違うのです。写っているのは写真家アントワーヌ・クローデとトールボットの助手ニコラース・ヘネマンらしく、クローデのスタジオで撮られたものがヘネマンの手に渡り、借金の返済の一部としてトールボットに渡ったのでは、という説があります（美術館の解説）。"],"spots":[["盤","テーブルの上のチェス盤。駒がずらりと並んでいます。"],["シルクハットの男","帽子をかぶったまま、駒に手をかけています。"],["考えこむ男","あごに手を当て、盤をじっと見つめる相手。"],["幕","うしろに下がった幕。撮影のための背景でしょうか。"],["もうひとつの帽子","右の台の上に、もうひとつのシルクハットが置かれています。"]]},"pvl":{"title":"さいころ遊びをする男たち","artist":"PVLの画家","date":"1520年ごろ","place":"ネーデルラント","game":"さいころ","medium":"紙に銅版画（エングレーヴィング）","size":"9.4×9.4cm（円形）","credit":"チャールズ・ハック／ハーン家信託コレクション、2023年購入","p":["16世紀のはじめにネーデルラントで活動した、名前のわからない銅版画家の作品です。左下に「PVL」の組み文字が刻まれているので、「PVLの画家」と呼ばれています。手のひらにのるほどの丸い版画に、細い線をびっしり刻んで、部屋の奥行きや服の質感を表しています。","テーブルの上には2つのさいころ。身をのりだした男と毛皮のえりの若者が、指をさして何か言い合っています。目の数をめぐる争いでしょうか。うしろでは女性たちが勝負をのぞきこみ、テーブルの下には酒のつぼが置かれています。さいころは古代から賭けと結びつき、たびたび禁止されてきた遊びでした。"],"spots":[["さいころ","テーブルの上に転がる2つのさいころ。"],["指さす手","2人の指がテーブルの上でぶつかります。目の数をめぐる言い合いでしょうか。"],["つば広帽の男","身をのりだす男。切れ込みの入ったふくらんだ袖は、当時はやった服です。"],["毛皮のえりの若者","大きな帽子と毛皮のえりの若者。"],["見物の女性たち","うしろから勝負をのぞきこむ女性たち。"],["組み文字","左下の「PVL」。この画家の名前の手がかりです。"]]},"kiyohiro":{"title":"双六をする人々","artist":"鳥居清広","date":"1750年ごろ","place":"日本（江戸時代）","game":"盤双六","medium":"紅摺絵（多色木版、大判）。版元は鱗形屋","size":"43.5×29.3cm","credit":"クラレンス・バッキンガム・コレクション","p":["鳥居清広は1737年ごろから1776年ごろまで活動した浮世絵師です。この絵は「紅摺絵」。紅（べに）と緑など少ない色の版を重ねた刷り方で、何色も重ねる「錦絵」が1765年に生まれる前の時代の色づかいです。","黒い台の盤で遊んでいるのは盤双六。2人がさいころを振り、白と黒の駒を進めて、先に自分の駒をすべて上がらせたほうが勝ちです。西洋のバックギャモンと同じ仲間のゲームで、浮世絵には女性たちが盤双六を楽しむ姿がたびたび描かれました。うしろの女性はキセルをくゆらせて勝負を見守っています。"],"spots":[["盤","台つきの双六盤。白と黒の駒が並んでいます。"],["左の人物","盤に手をのばして駒を動かしています。"],["右の女性","盤に身をかがめて、駒を見つめる相手。"],["キセルの女性","長いキセルをくゆらせて、うしろから勝負を見守ります。"],["掲げた手","右の女性が黒い小さなものを掲げています。さいころを振る筒でしょうか。"],["署名","「鳥居清廣筆」の署名と、版元・鱗形屋の印。"]]},"ingram":{"title":"中国のチェス（シャンチー）","artist":"ジョン・イングラム（ブーシェの原画による）","date":"1741〜63年","place":"フランス（パリ）","game":"シャンチー","medium":"エッチングとエングレーヴィング","size":"紙39.4×27.7cm（版24.5×16.4cm）","credit":"エリシャ・ウィッテルジー・コレクション、1966年","p":["フランスの画家フランソワ・ブーシェの素描を、ロンドン生まれの版画家ジョン・イングラムが銅版にしたものです。イングラムはパリに移り、1741年から1763年にかけて、ブーシェの「シノワズリー」（ヨーロッパの人が思い描いた中国風）の絵を次々に版画にしました。下の題は「LE JEU D'ECHETS CHINOIS（中国のチェス遊び）」です。","髪を高く結った女性が、ひざの上の盤で駒を動かし、そばで小さな子が見ています。描かれたゲームは中国のシャンチーとされますが、本物のシャンチーの駒はすべて平たい円盤なのに、ここでは背の高い駒や小さな四角い駒が並んでいます。ヤシの木や、壺の上に座る像も、実際の中国というより、当時のヨーロッパが夢見た遠い国の姿です。"],"spots":[["盤と駒","ひざの上の盤。背の高い駒と四角い駒が並びます。本物のシャンチーの駒は平たい円盤です。"],["駒をつまむ手","女性の右手が駒を動かしています。"],["ほおづえ","左手をあごに当てて、盤を見下ろしています。"],["のぞきこむ子","盤のそばに立って勝負を見つめる子。"],["壺の上の像","大きな壺の上にあぐらをかいて座る像。"],["題と名前","「ブーシェ素描」「イングラム彫版」の名と、題「LE JEU D'ECHETS CHINOIS」。"]]},"posada":{"title":"ガチョウのゲーム","artist":"ホセ・グアダルーペ・ポサダ","date":"1909年","place":"メキシコ","game":"ガチョウのゲーム","medium":"亜鉛凸版、紙","size":"29.3×39.4cm","credit":"ウィリアム・マッカリン・マッキー記念基金","p":["骸骨の絵「カラベラ」で知られるメキシコの版画家ポサダが、メキシコシティの版元アントニオ・バネガス・アロヨのために作った、遊ぶための一枚刷りです。左下の帯に「JUEGO DE LA OCA（ガチョウのゲーム）」とあり、1のマスから63まで、渦を巻いて中心へ進みます。","中央には遊び方（EXPLICACION）が刷られています。最初の一振りが5と4なら26へ、6と3なら53へ。ガチョウ（鳥）のマスに止まれば同じ数だけもう一度進み、19の宿屋（Venta）では2回休み、31の井戸（Poso）と52の牢屋（Carcel）は誰かが来るまで出られず、42の迷路で39へ戻り、58の死（Muerte）でふりだしへ。ちょうど63で上がりです。止まるたびに賭け金を払う決まりもあり、賭けの遊びでもありました。"],"spots":[["遊び方","中央の「EXPLICACION」。止まったマスごとの決まりと賭け金の払い方が書かれています。"],["1のマス","ふりだし。ここから渦を巻いて中心へ進みます。"],["井戸（31）","噴水のような井戸。ここに落ちると、誰かが来るまで出られません。"],["死（58）","骸骨のマス。止まるとふりだしに戻ります。"],["題の帯","左下の帯に「JUEGO DE LA OCA（ガチョウのゲーム）」。その下で子どもたちが遊んでいます。"],["版元の名","女神が持つ帯に「IMPRENTA DE A. VANEGAS ARROYO」。ポサダの版画を数多く出した版元です。"]]},"jintile":{"title":"盤上の遊びをする女性たちのタイル","artist":"作者不明","date":"1200年代","place":"中国（金）","game":"盤上の遊び（碁と思われる）","medium":"土器（陶製の浮き彫り）","size":"高さ27.3cm、幅24.8cm、厚さ5.4cm","credit":"アジア美術友の会の寄付による購入、2002年","p":["北中国を治めた女真族の王朝・金（1115〜1234年）の時代に焼かれた、浮き彫りのタイルです。花の咲く木の下、台の上に2人の女性が向かい合って座り、そのあいだに盤が置かれています。","盤には細かい升目が刻まれていて、碁を打っているところと思われます。右の女性は身をのりだして盤の上を指さし、左の女性はそれを見ています。金の時代の北中国の墓には、日々の暮らしを浮き彫りにした煉瓦で壁を飾ったものが多く知られていて、このタイルもそうした墓を飾ったものと思われます。"],"spots":[["盤","細かい升目の盤。碁盤と思われます。"],["指さす手","右の女性が盤の上を指さしています。次の一手でしょうか。"],["左の女性","髪を高く結い、盤を見つめる相手。"],["右の女性","身をのりだして盤に向かう女性。"],["花の木","2人の頭上に、花の咲く木の枝が広がります。"],["台","2人が座る台。脚のあいだに波形の飾りがあります。"]]},"kyosai":{"title":"おならで碁がひっくり返る（画帖より）","artist":"河鍋暁斎","date":"1800年代半ば〜後半","place":"日本（江戸〜明治時代）","game":"囲碁","medium":"画帖（折本、26の見開き）のうち一図。紙本墨画淡彩","size":"画帖（閉じた状態）28×18cm","credit":"アン・ダフェイとアンソニー・ダフェイ寄贈（エヴァン・ターナーをたたえて）","p":["幕末から明治にかけて活躍した絵師・河鍋暁斎（1831〜1889年）の画帖の一場面です。折りたたみ式の画帖に、筆の勢いにまかせた素早い墨の線で描かれています。暁斎は狩野派の確かな技を持ちながら、妖怪や戯画、風刺画でも人気を集めました。","美術館の付けた題は「おならが碁をひっくり返す」。左の烏帽子の男が身をかがめた先で、右では碁盤が宙に舞い、碁笥から碁石が雨のようにこぼれ、相手の男はひっくり返っています。真剣勝負の碁を、たった一発で台なしにするばかばかしさ。昔の絵巻にも描かれた「屁」の笑いを、暁斎らしいすばやい筆で描いています。"],"spots":[["烏帽子の男","身をかがめてお尻を突き出す男。騒ぎのもとでしょうか。"],["宙に舞う碁盤","升目の碁盤が、ななめに吹き飛んでいます。"],["碁笥と碁石","碁石を入れる碁笥が2つ、ひっくり返って石が降りそそぎます。"],["扇","碁盤のそばに、開いた扇も飛ばされています。"],["ひっくり返った相手","あおむけに倒れて、目を丸くする男。"],["筆の線","下描きなしで一気に引いたような、勢いのある墨の線。"]]},"yokuts":{"title":"賭けの遊びの盆","artist":"ヨクーツ族の織り手（名前不明）","date":"1900年ごろ","place":"アメリカ（カリフォルニア州ダンラップ近く）","game":"フーチュイシュ（クルミのさいころ）","medium":"植物繊維（コイル編み）","size":"高さ5.1cm、直径61cm","credit":"レナード・S・フロースハイム・ジュニア夫人の資金による購入","p":["カリフォルニアの先住民の多くは、運まかせの遊びをしていました。この盆は「フーチュイシュ」という、女性だけが遊んださいころの遊びに使われたものです。8つのクルミの殻のさいころを盆の上に投げ、点数は棒で数えました。","盆に織り込まれた円い模様には、その遊びそのもの――さいころ、点数を数える棒、遊ぶ人たち――が表されています（美術館の解説）。遊ぶための道具に、その遊びの絵を描いた品です。写真では盆の上とまわりに、クルミの殻のさいころが置かれています。"],"spots":[["遊ぶ人たち","ふちをめぐって並ぶ人の姿。遊びに加わる人たちです。"],["点数の棒","縦の短い線の束。点数を数える棒を表しています。"],["丸い模様","小さな丸い模様。さいころを表したものでしょうか。"],["クルミのさいころ","クルミの殻のさいころ。8つを盆に投げて遊びました。"],["三角の帯","濃い色の三角を連ねた帯。盆をぐるりと一周します。"],["中心の輪","中心から渦を巻く編み目と、それを囲む輪の模様。"]]},"hokkei":{"title":"牛若丸、双六で弁慶を負かす","artist":"魚屋北渓","date":"1825年ごろ","place":"日本（江戸時代）","game":"盤双六","medium":"摺物（色紙判の多色木版）","size":"21.8×19.1cm","credit":"ヘレン・C・ガンソーラス寄贈","p":["葛飾北斎の門人、魚屋北渓（1780〜1850年）の摺物です。摺物は、狂歌の仲間などが自分たちの歌を入れて特別に刷らせた版画で、売り物の浮世絵よりも上等な紙や金属の顔料を使い、ぜいたくに仕上げられました。","源義経の少年時代・牛若丸と、怪力の僧兵・弁慶。2人の出会いといえば京都の五条大橋での対決が有名ですが、この摺物では勝負が盤双六に置きかえられています。牛若丸は涼しい顔で盤の向こうに座り、なぎなたを背負った弁慶は頭をかいて負けを認めています。見立ての遊びと思われます。"],"spots":[["双六盤","箱形の双六盤。白と黒の駒が並んでいます。"],["頭をかく弁慶","鎧姿の弁慶が、負けて頭をかいています。"],["牛若丸","盤の向こうに座る、少年の牛若丸。"],["なぎなた","弁慶が背負う大なぎなたの刃。"],["狂歌","右上に書かれた歌。摺物を作らせた仲間の歌と思われます。"],["署名","右下の枠に北渓の署名。"]]},"vorsterman":{"title":"バックギャモンをする人々（夜の場面）","artist":"リュカス・エミール・フォルステルマン（アダム・デ・コステルの原画による）","date":"1630年ごろ","place":"フランドル（アントワープ）","game":"バックギャモン","medium":"エングレーヴィング、象牙色の紙","size":"図25.5×34.4cm","credit":"バーナード・F・ロジャーズ・コレクション","p":["アダム・デ・コステルは、1630年ごろのアントワープで、ろうそくに照らされた夜の場面を得意とした画家でした。同じころ同じ町で、フォルステルマンは人気の画家たちの絵を銅版画にしていました。ルーベンスの弟子だったフォルステルマンは、師と仲たがいしてイギリスへ渡ったあと、明暗の強い、カラヴァッジョ風の版画を作るようになります。","暗い部屋のテーブルで、男たちがバックギャモンの盤を囲んでいます。デ・コステルの光の扱いにならい、2本のろうそくの炎がテーブルのまわりの顔を照らしています（美術館の解説）。右ではリュートを抱えた若者がこちらを見ています。"],"spots":[["盤","テーブルの上の、箱形に開いたバックギャモン盤。"],["ろうそく","燭台のろうそく。炎が人々の顔を照らします。"],["パイプの男","つば広帽の男がパイプをくわえて勝負を見ています。"],["背を向けた男","テーブルに手をついて身をのりだす男。"],["リュートの若者","リュートを抱えて、こちらに笑いかける若者。"],["名前","左下に「A. De Coster pi.（デ・コステル画）」、右下に「Vorsterman」。"]]},"zorn":{"title":"チェスをする人々","artist":"アンデシュ・ソーン","date":"1891年","place":"スウェーデン","game":"チェス","medium":"エッチング、象牙色の簀目紙","size":"図13.5×9.6cm（版13.9×10cm）","credit":"ウォレス・L・デウルフとチャールズ・ディアリングのソーン版画コレクション","p":["スウェーデンの画家アンデシュ・ソーン（1860〜1920年）のエッチングです。ソーンは油彩や水彩の肖像画で国際的に名を上げると同時に、銅版画でも大きな仕事を残しました。手のひらほどの小さな版です。","斜めに走るすばやい線を重ねるだけで、暗い部屋と人の姿が浮かび上がります。手前の男は背を向けて盤をのぞき込み、向かいの人物はうつむいて次の手を考えています。盤の上には、細い線で駒が描かれています。だれを描いたのかは記録に残っていません。"],"spots":[["盤と駒","下の明るい部分が盤。短い縦の線が駒です。"],["手前の男","背を向け、盤の上に身をかがめる男。"],["向かいの人","うつむいて盤を見つめる相手。"],["暗い背景","縦に重ねた線で作った、暗い部屋の奥。"],["斜めの線","上着は斜めの速い線を重ねて表しています。"],["署名","版の下に鉛筆で「Zorn」の署名。"]]},"harunobu-sugoroku":{"title":"勝負を見る（盤双六）","artist":"鈴木春信","date":"1766年ごろ","place":"日本（江戸時代）","game":"盤双六","medium":"多色木版（中判、摺物）","size":"28.5×21cm","credit":"クラレンス・バッキンガム・コレクション","p":["鈴木春信（1725?〜1770年）は、何色もの版を重ねて刷る「錦絵」が1765年ごろに生まれたとき、その中心にいた浮世絵師です。この絵は特別に刷られた摺物で、やわらかな色の重なりにその新しさが表れています。","梅の咲く座敷で、2人の娘が箱形の双六盤をはさんで遊び、もう1人が立ったまま盤をのぞき込んでいます。盤には白と黒の駒が並び、左の娘は駒を動かし、右の娘も盤に手をのばしています。襖には滝と松の絵が描かれています。"],"spots":[["双六盤","箱形の盤双六の盤。白と黒の駒が並んでいます。"],["左の娘","折り鶴の模様の着物。駒を動かしています。"],["右の娘","身をかがめて、盤に手をのばす相手。"],["見物の娘","立ったまま勝負をのぞき込む娘。手に長い柄の道具を持っています。"],["梅","上から枝をのばす白梅。"],["襖の絵","滝と松を描いた襖。"]]},"kota":{"title":"クリシュナを礼拝するコータの王キショール・シング2世","artist":"作者不明","date":"1825年ごろ","place":"インド（ラージャスターン、コータ）","game":"パチーシ","medium":"紙にゴム・テンペラ、銀、金","size":"24.5×18.8cm","credit":"ジェームズ・アルバートとメアリー・ガーディナー・フォード記念基金","p":["ラージャスターンの小さな藩王国コータの王（在位1819〜28年）が、プシュティ・マールグ派の司祭の姿で、5つの炎のともる灯明をささげています。祭壇の小さな堂には、クリシュナと2人の妃の金属の像がまつられています。この像はコータだけで礼拝されるものです。","天井からはたくさんのガラスのランプが下がり、祭壇へ上がる段には、クリシュナと仲間たちを楽しませるおもちゃや遊び道具が並べられています。真ちゅうの象、銀の牛、まり、そしてパチーシの盤（美術館の解説）。赤い十字の布がその盤で、パチーシが神さまの遊び道具として供えられていたことがわかります。"],"spots":[["パチーシの盤","段の上の、赤い十字形の布。パチーシの盤です。"],["象","真ちゅうの象が2頭、盤のそばに並びます。"],["まり","上の段に置かれた金色のまり。"],["クリシュナの像","小さな堂にまつられた、クリシュナと2人の妃の像。"],["王と灯明","司祭の姿の王が、5つの炎の灯明をささげています。"],["ガラスのランプ","天井から下がる、たくさんのガラスのランプ。"]]},"coyote":{"title":"コヨーテのゲーム","artist":"ホセ・グアダルーペ・ポサダの追随者","date":"年代不明","place":"メキシコ","game":"コヨーテとめんどり（キツネとガチョウの仲間）","medium":"亜鉛凸版、紙","size":"38.2×30.5cm","credit":"ウィリアム・マッカリン・マッキー記念基金","p":["ポサダがメキシコシティの大衆向けの版元のために作ったものと同じ、亜鉛凸版で刷った遊ぶための一枚刷りです。上に大きく「JUEGO DEL COYOTE（コヨーテのゲーム）」、まわりには鶏小屋をねらうコヨーテや、棒を振り上げて追い払う人が描かれています。下の帯には「イルデフォンソ・T・オレリャーナの所有」とあります。","下の「EXPLICACION」に遊び方が刷られています。2人で遊び、一方は15のめんどり、もう一方はコヨーテ1匹。めんどりは前と横にしか進めず、後ろへは戻れません。コヨーテはどの向きにも動け、すぐ後ろが空いていればめんどりを跳び越えて食べます。めんどりはコヨーテを囲んで動けなくすれば勝ち。ヨーロッパの「キツネとガチョウ」と同じしくみの追い込みゲームです。"],"spots":[["コヨーテのマス","中央の円に描かれたコヨーテの顔。ここからコヨーテが始めます。"],["めんどりのマス","めんどりの絵の円。ここにめんどりの駒を並べます。"],["遊び方","「EXPLICACION」。駒の数や動き方、勝ち負けが書かれています。"],["題","「JUEGO DEL COYOTE（コヨーテのゲーム）」。"],["めんどりをくわえるコヨーテ","左下では、コヨーテがめんどりをねらっています。"],["棒を振る人","右上では、棒を振り上げてコヨーテを追う人。"]]},"mons":{"title":"モンス（ベルヘン）をかけたトリックトラック、1709年","artist":"ピーテル・ノルペ（版の制作・発行）","date":"版は1623〜53年、刷りは1709年ごろ","place":"オランダ（アムステルダム）","game":"トリックトラック（バックギャモンの仲間）","medium":"エッチング、エングレーヴィング、活字の詩","size":"紙35.8×18.6cm（版12.9×17.5cm）","credit":"","p":["4人の男がテーブルでトリックトラックを打っています。美術館の記録によると、記号のA〜Dはマールバラ公、バイエルン選帝侯、アウウェルケルク卿、ヴィルロワ公。1709年、連合軍がフランス側からモンス（オランダ語でベルヘン）を包囲して奪った出来事を、町をかけた盤の勝負に見立てた風刺版画です。奥の部屋（E）では、スペイン王フェリペ5世が女性といます。","版に「ノルペ作・発行」とある画家ピーテル・ノルペは1650年代はじめに亡くなっているので、17世紀の古い版に記号と新しい詩を足して刷り直したものと思われます。下の詩は、えらい殿方の遊びはトリックトラック（tiktak）とフェルケール（verkeer）ばかり、と始まり、記号ごとに勝負の行方を皮肉っています。"],"spots":[["盤","テーブルの上のトリックトラック盤。町をかけた勝負です。"],["A マールバラ公","立って盤を見下ろす男。連合軍を率いたイギリスの将軍です。"],["B バイエルン選帝侯","帽子をとって椅子に深く座る男。"],["C アウウェルケルク卿","羽根飾りの帽子の男。オランダ軍の将軍です。"],["E 奥の部屋","窓の向こうの寝室に、フェリペ5世と女性。"],["詩","下に活字で刷られたオランダ語の詩。A〜Eごとに勝負を皮肉ります。"]]},"stembus":{"title":"投票箱──政治のガチョウのゲーム","artist":"ヨハン・ミカエル・シュミット・クランス（版画）","date":"1867年","place":"オランダ","game":"ガチョウのゲーム（風刺）","medium":"リトグラフ","size":"66×50cm","credit":"","p":["ガチョウのゲームの形をした風刺版画です。週刊誌『デ・ネーデルラントセ・スペクタトル』の1867年3月2日号に付いたもので、遊び方を書いた別紙も付いていました（美術館の記録）。マスにはそのころの大臣たちの肖像が入っています。","ふりだしはハーグの国会議事堂ビネンホフ。上がりは盤の中央、64番目の「インスリンデ」（オランダ領東インドの雅名）で、ジャワ島に吊るされた大臣ピーテル・マイエルの肖像画が待っています。マイエルは植民地大臣から東インド総督になり、この人事が政界の大騒ぎになっていました。ふつう63マスのガチョウのゲームより1マス多いのも、この落ちのためと思われます。"],"spots":[["ふりだし","左上の建物。ハーグのビネンホフ（国会）から始まります。"],["マイエルの肖像","63のマス。額に入ったピーテル・マイエルの肖像が、ロープで島に吊られています。"],["インスリンデ 64","中央の島と「64」の文字。ここが上がりです。"],["投票箱","右下の「DE STEMBUS（投票箱）」。題になった箱です。"],["大臣たち","マスの窓には、当時の大臣たちの顔が並びます。"],["おんどり","マスの中のおんどり。何を皮肉ったのかはわかっていません。"]]},"koorai":{"title":"盤を囲む朝鮮の人々（シーボルト『日本』より）","artist":"ジェームズ・エルクスレーベン（石版）、「トイオスケ」の原画による","date":"1832〜52年","place":"オランダ（ライデン）／朝鮮の人々","game":"盤の遊び（碁と思われる）","medium":"トーン・リトグラフ、手彩色","size":"紙38×55.5cm","credit":"F・G・ワラー寄贈","p":["ドイツ生まれの医師シーボルトが、長崎のオランダ商館にいたころ（1823〜30年）の見聞をもとにライデンで出版した大著『日本（NIPPON）』の一図です。右上に「TAB. I」、下に「KOORAI（高麗）」とあり、オランダ語とドイツ語で「漁師の一家」と添えられています。石版はエルクスレーベン、原画の作者は版に「トイオスケ」と記されています。","4人の男が地面に座って盤を囲み、左には子どもの手を引く女性、右には長い棒と袋を持つ男が立っています。手前には黒いつば広の帽子（カッ）が置かれています。盤には升目と丸い石が描かれていて、碁（韓国語でパドゥク）と思われますが、記録には「盤の遊び」とだけあります。"],"spots":[["盤","升目に丸い石。碁（パドゥク）を打っているところと思われます。"],["黒い帽子","地面に置かれた、つば広の黒い帽子（カッ）。"],["母と子","子どもの手を引いて勝負を見る女性。"],["立つ男","長い棒と袋を持って立つ男。"],["身をかがめる男","青い上着の男が、盤をのぞき込みます。"],["題","「KOORAI（高麗）」、オランダ語とドイツ語で「漁師の一家」。"]]},"cairo":{"title":"カフェの前で盤を囲む人々（カイロ）","artist":"デリエ＆ベシャール（イポリット・デリエ、エミール・ベシャール）","date":"1869〜90年ごろ","place":"エジプト（カイロ）","game":"盤の遊び（チェスと思われる）","medium":"鶏卵紙プリント","size":"10.8×16.4cm","credit":"","p":["カイロで写真館を開いていたフランス人の写真家、イポリット・デリエとエミール・ベシャールの写真です。台紙には「エズベキーヤ庭園のそば」という写真館の名と「カイロ（エジプト）」が刷られています。こうした写真は、エジプトを訪れた旅行者が記念に買い求めました。","格子窓のある店先の地面に男たちが座り、低い台の上の盤を囲んでいます。盤には背の高い駒がいくつも立っていて、チェス（アラビア語でシャトランジ）と思われますが、美術館の記録には「盤の遊び」とだけあります。撮影のため、人びとは動かずにじっとしています。"],"spots":[["盤と駒","低い台の上の盤。背の高い駒が並び、チェスと思われます。"],["格子窓","木の格子をはめた窓。カイロの古い家並みによく見られる作りです。"],["杖の男","杖を持って座り、勝負を見る男。"],["籠","地面に置かれた編み籠。"],["見物の子","うしろから盤をのぞく子ども。"],["写真館の名","台紙の「AU JARDIN DE L'ESBÉKIEH」「CAIRE (EGYPTE)」の文字。"]]},"vanmour":{"title":"カード遊びをするアルメニア人の集まり","artist":"ジャン＝バティスト・ヴァンムール","date":"1720〜37年ごろ","place":"オスマン帝国（イスタンブール）","game":"カード遊び","medium":"油彩・カンヴァス","size":"44.5×58.5cm","credit":"","p":["フランドル生まれの画家ヴァンムールは、1699年にフランス大使に連れられてイスタンブールへ渡り、亡くなるまでこの都で暮らして、宮廷の行事や町の人びとの暮らしを描きました。この絵の男たちは、服装からアルメニア人だとわかると美術館は記しています。","大きなろうそくの明かりのもと、男女が赤い布の卓を囲んでカードをしています。卓の上には配られたカード、手に札を持って見入る人もいます。左の隅では年老いた女性が糸を紡いでいます。何という遊びかは記録にありません。"],"spots":[["卓のカード","赤い布の卓に置かれたカード。"],["大きなろうそく","一座を照らす一本のろうそく。"],["糸を紡ぐ老女","左の隅で糸を紡ぐ年老いた女性。"],["札を見る女性","手札をじっと見る右端の女性。"],["毛皮の男","毛皮の縁取りの上着を着た男。服装からアルメニア人とされます。"],["手を伸ばす人","卓に身を乗り出してカードを持つ人。"]]},"algiers":{"title":"盤の遊びをする三人の男（アルジェ）","artist":"作者不詳","date":"1851〜1900年","place":"アルジェリア（アルジェ）","game":"盤の遊び（バックギャモンと思われる）","medium":"鶏卵紙プリント","size":"14.0×10.0cm","credit":"","p":["写真の下に手書きで「Alger（アルジェ）」と書かれた、作者のわからない写真です。無地の背景の前に椅子と小卓を並べているので、写真館で撮ったものと思われます。北アフリカの人びとの姿を写したこうした写真は、旅行者や収集家が買い求めました。","二人の男が縁のある盤をはさんで向かい合い、右の男がいま駒に手をかけています。盤の上には丸い駒が積み重ねてあり、バックギャモン（この地方ではタウラなどと呼ばれます）と思われますが、記録には「盤の遊び」とだけあります。手前の小卓にはコーヒーの道具が置かれています。"],"spots":[["盤と駒","縁のある盤に、丸い駒が積み重ねられています。"],["立って見る男","うしろに立ち、腰に帯を巻いて勝負を見下ろす男。"],["左の老人","頭に布を巻き、考え込む年配の男。"],["右の男","頭に白い布をかぶり、盤をのぞき込む男。"],["コーヒーの道具","透かし彫りの小卓に置かれた盆と小さな器。"],["駒を動かす手","いままさに駒をつまもうとする右の男の手。"]]},"circo":{"title":"サーカスゲーム（フエゴ・デル・シルコ）","artist":"マヌエル・マニーリャ（推定）","date":"年代不詳","place":"メキシコ","game":"サイコロ2個の賭けの遊び","medium":"凸版（木口木版または写真製版）・黄褐色の紙","size":"26.2×35.0cm","credit":"","p":["メキシコの版画家マヌエル・マニーリャの作とされる（美術館は「？」付き）、遊び用の一枚刷りです。右下には売り手として「エスタンペリア・エル・テアトロ」という版画店の名と住所が刷られています。こうした安い刷り物は町で売られ、家で切らずにそのまま遊ばれたと思われます。","真ん中にサーカス小屋、まわりに曲馬や人間ピラミッド、力持ちなどの絵が並び、それぞれに2から12の数がついています。左上の「説明」によれば、何人でも子どもでも遊べ、サイコロ2個を振って出た目の枠に賭け金を置き、すでに置かれていればそれをもらいます。12を出した人が場の全部を取ります。"],"spots":[["サーカス小屋","「JUEGO DEL CIRCO」の題と、12の枠になったサーカス小屋。"],["遊び方の説明","「ESPLICACION（説明）」に始まる遊び方の文。"],["曲馬","走る馬の背で踊る曲芸師。6の枠。"],["人間の塔","肩の上に人が立つ二人組。4の枠。"],["力持ち","大砲のような重りを持ち上げる男。8の枠。"],["版画店の名","「De venta, Estampería “El Teatro”」と住所。"]]},"loteria":{"title":"ロテリアの絵札","artist":"ホセ・グアダルーペ・ポサダ","date":"1880〜1913年","place":"メキシコ","game":"ロテリア（絵札の数合わせ）","medium":"凸版（木口木版または写真製版）・黄褐色の紙","size":"30.0×40.0cm","credit":"","p":["メキシコの版画家ポサダは、メキシコシティの版元アントニオ・バネガス・アロヨのもとで、ニュースや歌、遊び用の安い刷り物の絵を数多く手がけました。この一枚にも「JUEGO DE LOTERIA（ロテリアの遊び）」の題とバネガス・アロヨの名が刷られています。","星、月、さそり、悪魔、ガイコツ、雄鶏、印刷所など、名前を添えた小さな絵が38並んでいます。ロテリアは、読み手が札を引いて絵の名を呼び、手元の板にその絵があれば豆などで印をつける、ビンゴに似た遊びです。この紙は切り分けて札にしたものと思われます。"],"spots":[["題と版元","「JUEGO DE LOTERIA」とバネガス・アロヨの店の名。"],["星","「ESTRELLA」。左上の最初の絵。"],["月","「LUNA」。顔のある三日月。"],["死神","「MUERTE」。大鎌を持ち、笛を吹くガイコツ。"],["プルケ採り","「TLACHIQUERO」。リュウゼツランの汁を集める男。"],["印刷所","「IMPRENTA」。印刷機を動かす職人たち。こうした刷り物を作る場です。"]]},"jeupol":{"title":"「ジュ・ポロネ」すなわちダムの盤","artist":"作者不詳","date":"1833〜1900年","place":"ベルギーまたはオランダ","game":"ダム（10×10マスのチェッカー）","medium":"木版、活版の文字","size":"32.2×39.6cm","credit":"","p":["上に「JEU POLONAIS OF DAMSPEL」とフランス語とオランダ語の題が刷られた一枚刷りです。「ジュ・ポロネ（ポーランドの遊び）」は、フランスで10×10マスのダムを呼んだ名前です。右上には「n. 106」と、版元の通し番号が入っています。","美術館の記録のとおり、白黒50ずつ、あわせて100のマスが並び、左右に飾りの縁がついています。駒は刷られていないので、豆やボタンを駒にして、紙のまま遊ぶ安い盤だったと思われます。紙には折り目が残っています。"],"spots":[["題","「JEU POLONAIS OF DAMSPEL」の文字。"],["通し番号","版元の番号「n. 106」。"],["左の飾り縁","丸い花模様を縦に並べた縁。"],["右の飾り縁","左と同じ模様の縁。"],["100のマス","10×10の盤。黒いマスは細い線で刷られています。"],["折り目","紙に残る折り目。たたんで持ち歩いたのかもしれません。"]]},"dkaart":{"title":"ドミノとトランプの切り抜き紙","artist":"作者不詳（ブレポルス版）","date":"1800〜1833年","place":"ベルギー（トゥルンハウト）","game":"ドミノとトランプ","medium":"木版（青・赤・黄で彩色）、活版の文字","size":"34.3×41.9cm","credit":"","p":["美術館の記録によれば、切り抜いて使う32枚のトランプと28個のドミノを刷った一枚です。版元ブレポルスの目録の114番で、小売りの「D. プーウェルス（ベルヘン・オプ・ゾーム）」の名が下に入っています。題はオランダ語とフランス語で並んでいます。","左には0-0から6-6まで28個のドミノが三角形に並びます。右のトランプは各スートの7から10と絵札・エースの32枚で、ピケなどに使う組です。切り抜かれずに残ったので、刷られたままの姿が見られます。"],"spots":[["題","「DOMINO EN KAARTSPEL」の文字。"],["白の一対","三角形のてっぺん、目のない0-0のドミノ。"],["6-6","いちばん下の段の右端、最大の6-6。"],["スペードのエース","左の列の上から2枚目。"],["絵札","赤・青・黄で色をつけた王の札。"],["小売りの名","下の「D. POUWELS, Bergen-op-Zoom」。"]]},"apen":{"title":"トリックトラックをする二匹のサル","artist":"クイリン・ブール（ダーフィット・テニールスの原画による）","date":"1635〜1690年","place":"フランドル","game":"トリックトラック（バックギャモンの仲間）","medium":"エッチング","size":"11.0×14.5cm","credit":"","p":["人のしぐさをサルにやらせる「サルの絵」の連作（表題の版と六枚）の一枚です。左下に「D. テニールス原画・刊行、特許つき」とあり、フランドルの画家テニールスの図案をクイリン・ブールが版にしました。","美術館の記録のとおり、二匹のサルが床に座り、トリックトラックの盤をはさんでいます。左のサルはグラスでワインを飲み、右のサルは雄鶏の羽根を挿した帽子をかぶって、盤の駒に手をのばしています。酒と賭けごとにふける人間を笑う絵と思われます。"],"spots":[["盤","床に置いた二つ折りのトリックトラック盤。三角の目と駒が見えます。"],["左のサル","上着を着て盤の前に座るサル。"],["ワイングラス","左のサルが掲げるグラス。"],["羽根の帽子","右のサルの帽子に挿した雄鶏の羽根。"],["酒の壺","左のサルの足もとの壺。"],["銘","「D Teniers in et excud cum privilegio」の文字。"]]},"dstereo":{"title":"テーブルでドミノをする男たち（立体写真）","artist":"作者不詳","date":"1850〜1880年","place":"不明（オランダ語の書き込み）","game":"ドミノ","medium":"鶏卵紙プリント（ステレオ写真）","size":"8.5×17.0cm","credit":"","p":["左右にほとんど同じ写真を二枚並べたステレオ写真です。専用のめがね（ステレオスコープ）でのぞくと、奥行きのある立体に見えます。左端には手書きで「Het dominospel（ドミノ遊び）」と書かれています。","建物の前の日なたに机を出し、シャツ姿の男たちがドミノの牌を手にしています。二人が立って勝負をのぞき込み、右の男は白い帽子をかぶっています。動かずにいる必要があったので、場面は撮影のために組んだものと思われます。"],"spots":[["机の上の牌","手もとに伏せたドミノの牌。"],["白い帽子の男","右に座り、牌を持つ男。"],["スカーフの男","首にスカーフを巻き、立って見下ろす男。"],["左の男","ひじをついて牌を見る若い男。"],["書き込み","左端の手書き「Het dominospel.」。"],["もう一枚","右の写真。少しずれた位置から撮られていて、二枚で立体に見えます。"]]},"gojo":{"title":"碁を打つ二人の女性","artist":"作者不詳","date":"1870〜1891年","place":"日本","game":"囲碁と思われる","medium":"手彩色の鶏卵紙プリント","size":"9.0×13.5cm","credit":"","p":["白黒の写真に筆で色をつけた手彩色写真です。こうした写真は横浜などの写真館で外国人向けのみやげとして作られました。この一枚は、マニラへの旅の写真アルバムに貼られていたものです。","床の間ふうの飾りと屏風を背に、二人の女性が脚つきの盤をはさんで座り、左の女性が石を置いています。盤には白と黒の石が並び、囲碁と思われますが、美術館の記録には「盤の遊び」とあります。手前の盆には菓子や器が並んでいます。"],"spots":[["盤と石","脚つきの厚い盤に、白と黒の石。"],["石を置く手","左の女性が盤に石を置くところ。"],["左の女性","こちらを振り向く女性。帯を大きく結んでいます。"],["右の女性","縞の着物の女性。盤の上に手を添えています。"],["盆と器","手前に並ぶ菓子や湯のみ。"],["生け花","背後の台に置かれた花入れ。"]]},"meade":{"title":"チェスをする二人の男","artist":"チャールズ・リチャード・ミード、ヘンリー・ウィリアム・マシュー・ミード","date":"1852年","place":"アメリカ合衆国","game":"チェス","medium":"ダゲレオタイプ","size":"6.9×8.3cm","credit":"","p":["イギリス生まれでアメリカに渡ったミード兄弟の写真館が撮ったダゲレオタイプです。ダゲレオタイプは銀をめっきした銅板に直接像を作る写真で、焼き増しのできない一点ものでした。そのため小さな革張りのケースに金色の枠をつけて納めています。","二人の若い男が小さな台の上のチェス盤をはさみ、左の男が駒に指をかけています。右の男は胸に手を当てて盤を見つめています。長く動かずにいる必要があったので、指し手の途中を演じたポーズと思われます。"],"spots":[["チェス盤","花柄の布をかけた台の上の盤と白い駒。"],["左の男","駒に指をかける男。"],["右の男","盤を見下ろす男。"],["胸に当てた手","右の男の、考えこむような手。"],["台の布","花柄の布をかけた小さな台。"],["金色の枠","像を守る金色の枠とケース。"]]},"weiqidai":{"title":"碁を打つ道教の仙人のいる山水","artist":"伝 戴進","date":"明時代、15〜16世紀","place":"中国","game":"囲碁（囲棋）","medium":"掛軸、絹本著色","size":"175.2×106.7cm","credit":"","p":["明時代の画家、戴進（1388ごろ〜1462年）の作と伝わる大きな掛軸です。戴進は浙江の出身で、力強い筆の山水画で知られ、のちに「浙派」の祖とされました。そそり立つ崖と大きな木の下に、小さく人の姿が描かれています。","木陰の地面で、二人の仙人が縦横に線を引いた碁盤をはさんで座り、そばには果物の皿と器が置かれています。左にうずくまる人物は、山で仙人の碁を見ているうちに斧の柄が腐るほどの年月がたっていた木こりの話（「爛柯（らんか）」）を思わせますが、美術館の題は「碁を打つ道教の仙人」だけです。"],"spots":[["碁盤","縁のある碁盤に、細かい格子が描かれています。"],["ひげの仙人","長いひげの仙人。ゆったりと座って盤を見ます。"],["青い頭巾の仙人","盤に身を乗り出す仙人。ひざもとに碁石の器があります。"],["うずくまる人","左で盤をのぞく人物。爛柯の木こりとも思われます。"],["果物と器","盤の向こうに置かれた皿と壺。"],["落款と印","右上の署名と二つの朱印。"]]},"reise":{"title":"世界一周の旅（水路と陸路で）","artist":"作者不詳","date":"19世紀","place":"ドイツ語圏と思われる","game":"すごろく（サイコロ1個の賭けの遊び）","medium":"リトグラフ","size":"42.5×33.7cm","credit":"","p":["「世界一周の旅、水路と陸路で——新しく楽しいサイコロ遊び」とドイツ語で題された遊び用の一枚刷りです。円い盤に1から41のマスが並び、気球や帆船、蒸気船、汽車、各国の人などの絵が入っています。右下に「No. 107」と番号があります。","下にはドイツ語・英語・オランダ語・フランス語で遊び方が刷られています。参加者はまず15マルクを共同の「旅の財布」に払い、サイコロ1個を順に振って印を進めます。大きな絵のマスに止まると2マルクもらえ、絵のないマスでは2マルクの罰金、ちょうど41に着いた人が残りを全部取ります。"],"spots":[["41：駅馬車","中央のゴール。客を乗せた駅馬車と御者。"],["1：イギリス人","スタートのマス。シルクハットの「Engländer」。"],["気球","空に浮かぶ気球のマス。"],["帆船","帆をいっぱいに張った船。"],["汽車","煙を吐く蒸気機関車。"],["遊び方","四つの言葉で刷られた決まり。"]]},"huchten":{"title":"命を賭けたサイコロ","artist":"ヤン・ファン・フフテンブルフ","date":"1680〜1720年","place":"オランダ","game":"サイコロ","medium":"油彩・カンヴァス","size":"67.5×76.0cm","credit":"","p":["戦いの絵で知られたオランダの画家フフテンブルフ（1647〜1733年）の作で、左下に署名があります。美術館の題は「命を賭けたサイコロ遊び」。とりでの外で、二人の囚人が太鼓の上でサイコロを振り、将校や兵士が取り囲んでいます。","右の奥には絞首台が立ち、左のとりでの壁の上からも兵士たちが見ています。罪に問われた兵士のうち誰が刑を受けるかを、サイコロで決める場面と思われます。囚人の片方は太鼓を指さし、もう片方はひざをついて目をのぞき込んでいます。"],"spots":[["太鼓とサイコロ","盤のかわりの太鼓。この上でサイコロが振られます。"],["指さす囚人","立って太鼓を指さす囚人。"],["ひざをつく囚人","白いシャツで太鼓にかがみ込む囚人。"],["馬上の将校","帽子をかぶり、馬上から見下ろす将校。"],["絞首台","右上に立つ絞首台。"],["壁の上の兵士","とりでの壁から見物する兵士たち。"]]},"vertu":{"title":"徳の遊び（スペル・デル・ドゥフト）","artist":"ヤン・ヘリッツ・フィッセル（原案 J. フォールマン）","date":"1798年","place":"オランダ","game":"サイコロ2個の賭けの遊び","medium":"エングレーヴィング、エッチング、活版","size":"56.9×38.0cm","credit":"","p":["オランダ語とフランス語で「徳の遊び」と題された遊び用の大判の刷り物です。柱の並ぶ神殿の中央に「徳」が座り、左に「繁栄」、右に「貧しさ」が立ち、柱には誠実・感謝・愛などの徳のメダル、下の台には欲ばり・高慢・怠けなどの悪徳の絵が並びます。","下の決まりによれば、サイコロ2個で遊ぶか、くじを引いて遊びます。サイコロのときは場に合わせて63を賭け、日の巡る向きに順に振ります。出た目ごとに徳か悪徳が決まっていて、たとえば6のぞろ目の「徳」は場を全部取り、1のぞろ目の「悪徳」は8を払います。絵の下の「T」はもらう数、「B」は払う数です。"],"spots":[["題","破風の「SPEL DER DEUGD」の文字。"],["徳","中央の台に座る「徳（LA VERTU）」。6のぞろ目で場を全部取ります。"],["繁栄","豊穣の角を持つ「繁栄」。"],["悪徳","1のぞろ目の「悪徳（LE VICE）」。杯を掲げる子どもの姿。"],["欲ばり","台の「欲ばり（L’AVARICE）」。下の「B」とサイコロの目は払う数です。"],["遊び方","下段にびっしり刷られた決まり。"]]},"charros":{"title":"密輸人のチャロたち（サイコロの遊び）","artist":"ホセ・グアダルーペ・ポサダ","date":"年代不詳","place":"メキシコ","game":"すごろく（サイコロ3個）","medium":"リトグラフ","size":"29.9×40.4cm","credit":"","p":["「LOS CHARROS CONTRABANDISTAS（密輸人のチャロたち）／JUEGO DE DADOS（サイコロの遊び）」と題された、ポサダの絵のすごろくです。下に「A. バネガス・アロヨ印刷所、メキシコ」と版元の名、右下にポサダの署名があります。チャロはメキシコの牧童で、四隅にソンブレロ姿で馬を駆ける姿が描かれています。","縄で縁取った円いマスが盤いっぱいにくねり、動物や人、汽車などの絵が入っています。右上の「説明」によれば、サイコロは3個。最初に1を三つ出せば勝ち、ガイコツのマスに止まれば負け、シカのマスでは場から取り、泥棒のマスでは払い、ライオンのマスでは誰かが来るまで動けません。"],"spots":[["題","「LOS CHARROS CONTRABANDISTAS／JUEGO DE DADOS」。"],["説明","「EXPLICACION」で始まる遊び方。"],["遊ぶ人たち","左下で卓を囲み、盤で遊ぶ人びと。"],["サイコロ","盤の中ほどに描かれた3個のサイコロ。"],["馬上のチャロ","投げ縄を振るい、馬を駆けるチャロ。"],["版元の名","「IMPRENTA DE A. VANEGAS ARROYO, MÉXICO」。"]]},"snuffwq":{"title":"碁を打つ人物の描かれた嗅ぎたばこ入れ","artist":"中国","date":"清時代・道光年間（1820〜50年）、道光の款","place":"中国","game":"囲碁","medium":"磁器・上絵付け（粉彩）","size":"高さ5.7cm","credit":"","p":["清の時代、粉にしたたばこを入れて持ち歩いた小さな瓶です。美術館の記録では道光帝の年号の款があり、1820〜50年の作です。高さ6センチほどの白い磁器の胴に、上絵の具で山の景色と人びとが描かれています。","洞窟のような岩のそばで、二人の老人が青い台に載った碁盤をはさみ、左の老人は碁石を置こうとしています。その後ろでは杖を持った子どもが見ています。仙人の碁を見ていた木こりの話を思わせる題材と思われます。"],"spots":[["碁盤","青い台の上の碁盤。細かい格子が描かれています。"],["ひげの老人","紫の衣で、盤に手をのばす老人。"],["向かいの老人","右に座り、手をあげて盤を見る老人。"],["杖の子ども","うしろで杖を持って見ている子ども。"],["岩屋","背後の洞窟のような岩。"],["栓","緑色の栓。"]]},"ostade":{"title":"居酒屋でトリックトラックをする人々","artist":"アドリアーン・ファン・オスターデ","date":"1653年","place":"オランダ（ハールレム）","game":"トリックトラック（バックギャモンの仲間）","medium":"エッチング","size":"8.5×7.4cm","credit":"","p":["農民の暮らしを描いたハールレムの画家オスターデの、手のひらほどの小さなエッチングです。下に「A. ostade」と署名が刻まれています。暗い居酒屋の中、鉛の枠の窓からの光が人々を照らしています。","左の卓で二人がトリックトラックの盤をはさみ、うしろから一人がのぞき込んでいます。右では男が壁にもたれて座り、手に器を持っています。大きな酒の壺も床に転がり、のんびりした午後の店のようすと思われます。"],"spots":[["盤","卓に置かれたトリックトラックの盤。"],["左の打ち手","帽子をかぶり、盤に向かう男。"],["右の打ち手","盤に身をかがめる男。"],["のぞき込む男","うしろに立って勝負を見る男。"],["くつろぐ男","壁ぎわに座り、器を手にした男。"],["鉛の枠の窓","菱形の格子の窓。光はここから入ります。"]]},"lenain":{"title":"サイコロ遊びをする人々","artist":"マチュー・ル・ナンの追随者","date":"1630〜1680年","place":"フランス","game":"サイコロ","medium":"油彩・カンヴァス","size":"92.8×119.7cm","credit":"","p":["フランスの画家ル・ナン兄弟の末弟マチューの作風にならった画家の絵です。美術館によれば、同じような構図の素描がガブリエル・ド・サン＝トーバンの手で写されていて、パリの国立図書館にあります。","屋外の丸い卓を三人の男が囲み、サイコロを振っています。そのそばで二人が見物し、左の男は酒の瓶を抱えています。右には細身の猟犬が二頭、奥の窓の外には広い野が見えます。卓の上の小さな白いものがサイコロです。"],"spots":[["卓のサイコロ","丸い卓の上に転がるサイコロ。"],["白い帽子の男","腰かけて手を伸ばし、目を確かめる男。"],["黒い服の男","腰に手を当てて立つ若い男。"],["うしろの少年","卓のうしろから勝負を見る少年。"],["瓶を持つ男","左で瓶を抱え、こちらを見て笑う男。"],["二頭の猟犬","右手前の細身の犬たち。"]]},"tunisie":{"title":"アラブのカフェの前のカード遊び（アントワープ万博のチュニジア館）","artist":"作者不詳（印刷 Ch. ベルンヘフト）","date":"1894年","place":"ベルギー（アントワープ）","game":"カード遊び","medium":"コロタイプ","size":"15.4×21.6cm","credit":"","p":["1894年のアントワープ万国博覧会の写真49枚を収めた組の一枚で、上に「EXPOSITION UNIVERSELLE D’ANVERS 1894」、下に「チュニジア——アラブのカフェの前のカード遊び」と刷られています。印刷はルクセンブルクの宮廷写真家ベルンヘフトです。","万博のチュニジアの区画に造られた、ドームや塔のある広場で撮られています。チュニジアの服装の男たちが、タイル張りの小さな卓を囲んでカードをし、水たばこを吸う人や、茶碗の盆も見えます。右には背広の見物客が並び、遠い国の暮らしを見せる展示だったと思われます。"],"spots":[["カードの卓","タイル張りの小卓でカードを持つ男たち。"],["水たばこ","左の男がくわえる水たばこの管。"],["背広の見物人","右に座る背広の男たち。万博の客と思われます。"],["茶碗の盆","卓の下に置かれた小さな茶碗。"],["ドームと塔","背景に建てられたチュニジアふうの建物。"],["題","「TUNISIE」と「PARTIE DE CARTES DEVANT UN CAFÉ ARABE」。"]]},"laghouat":{"title":"ラグアト近郊のカーイドたち","artist":"作者不詳","date":"1880〜1890年","place":"アルジェリア（ラグアト近郊）","game":"ドミノと思われる","medium":"鶏卵紙プリント","size":"20.9×27.0cm","credit":"","p":["「アルジェリアの人びと——ラグアト近郊のカーイドたち」と題された写真で、アルバムに貼られ、「239」の番号が刷られています。カーイドは、フランス統治下のアルジェリアで地方をまとめた長の呼び名です。","土壁の前の敷物に白い衣の男たちが座り、低い台の上に細長い牌を並べています。並べ方からドミノと思われますが、美術館の記録には「遊び」とだけあります。手前には茶の盆と脱いだ履物が置かれています。"],"spots":[["低い台の牌","台の上に一列に並べた細長い牌。"],["茶の盆","手前の盆に並ぶ茶碗とポット。"],["脱いだ履物","敷物の外にそろえた履物。"],["うしろに立つ人","壁ぎわに立って見ている人。"],["土壁","背景の、ごつごつした土の壁。"],["敷物","男たちが座る編んだ敷物。"]]},"hangong":{"title":"漢宮春暁図（部分）","artist":"仇英による模写","date":"清時代（1644〜1911年）","place":"中国","game":"囲碁（囲棋）","medium":"巻物、絹本著色","size":"36.2×454.4cm（全体）","credit":"","p":["明の画家、仇英（1494〜1552年）の構図を清の時代に写した、長さ4.5メートルを超える巻物の一部分です。春の日の宮殿で、女官や少女、侍女たちがぶらんこに乗り、遊び、牡丹を愛で、楽を奏で、琴を弾き、オウムや魚にえさをやる様子が、右から左へ続きます。","この場面では、欄干の奥で二人の女性が碁盤をはさみ、ほかの女性が身を乗り出してのぞき込んでいます。手前には太湖石を据えた蓮の鉢があり、侍女たちが楽器や包みを運んでいます。美術館の説明にあるとおり、宮殿の奥で暮らす女性たちの日々を理想化して描いた絵です。"],"spots":[["碁盤","欄干の奥の卓に置かれた碁盤。"],["石を打つ女性","盤に手をのばす薄紫の衣の女性。"],["のぞき込む女性たち","身をかがめて盤面を見る女性たち。"],["団扇の女性","柱のあいだで団扇を持つ女性。"],["太湖石","蓮の形の鉢に据えた青い奇石。"],["楽器を抱える侍女","琵琶と思われる楽器を抱えて歩く侍女。"]]},"homerbg":{"title":"バックギャモン","artist":"ウィンスロー・ホーマー","date":"1877年ごろ","place":"アメリカ合衆国","game":"バックギャモン","medium":"木口木版","size":"","credit":"","p":["アメリカの画家ウィンスロー・ホーマー（1836〜1910年）の絵による木口木版です。ホーマーは若いころ雑誌の挿絵画家として、こうした版画のための絵を数多く描きました。下には「396.—BACKGAMMON.—WINSLOW HOMER.」と刷られていて、番号つきで本か雑誌に載った一枚と思われます。","飾りのついたソファに二人の女性が向かい合って座り、ひざの上に渡した盤でバックギャモンをしています。盤の上には白い丸いものが見えますが、何かははっきりしません。長いスカートの襞や、ソファの渦巻く肘かけが細い線で刻まれています。"],"spots":[["盤","二人のひざの上に渡した盤。"],["左の女性","髪をまとめ、盤に手をのばす女性。"],["右の女性","身を乗り出して盤を見る女性。"],["ソファの肘かけ","渦巻き形の肘かけ。"],["スカート","細い線で刻んだ長いスカートの襞。"],["題","下の「396.—BACKGAMMON.—WINSLOW HOMER.」の文字。"]]},"chessst":{"title":"チェスをする男女（立体写真）","artist":"作者不詳","date":"1852〜1858年","place":"不明","game":"チェス","medium":"ステレオ写真（色つき）","size":"8.3×16.5cm","credit":"","p":["英語で「The Chess Players（チェスをする人たち）」と呼ばれる、二枚一組のステレオ写真です。ステレオスコープでのぞくと、盤と駒が手前に浮き出て見えます。白黒の写真の上から、赤いカーテンや黄色い服に色がつけられています。","黄色い服の女性が駒に手をかけ、向かいの男性は背中を見せて盤を見つめています。盤には赤と白の駒が並び、勝負の途中に見えますが、写真館で組んだ場面と思われます。19世紀半ばには、こうした家庭の情景のステレオ写真が広く売られました。"],"spots":[["盤と駒","格子の盤に並ぶ赤と白の駒。"],["駒を動かす手","女性が駒に手をかけるところ。"],["女性","白い襟と黄色い服の女性。うつむいて盤を見ます。"],["男性","背中を向けて座る男性。"],["赤いカーテン","背景の、色をつけたカーテン。"],["もう一枚","右の写真。二枚を立体鏡でのぞくと奥行きが出ます。"]]},"corrida":{"title":"闘牛のサイコロ遊び（コリーダ・デ・トロス）","artist":"ホセ・グアダルーペ・ポサダ","date":"1898年","place":"メキシコ","game":"すごろく（サイコロ2個の賭けの遊び）","medium":"写真製版の凸版・紙","size":"40.4×30.0cm","credit":"","p":["「CORRIDA DE TOROS（闘牛）」と題された、ポサダの絵のすごろくです。マスはうず巻きに並び、外側の1から中心へ向かうにつれて、闘牛の技や場面が順に描かれています。中心には闘牛場の建物、下にはアントニオ・バネガス・アロヨの印刷所の名があります。","下の「説明」によれば、二人以上で賭け金を出し、サイコロ2個を振って進みます。たとえば5の「棒高跳び」は10へ進み、12の「ピカドールの角突き」では払って休み、28の「胸のパセ」は最初からやり直し。32の「牛を引き出す」に着いた人が賭け金を全部取ります。"],"spots":[["題","「CORRIDA DE TOROS」の文字。"],["闘牛場","うず巻きの中心に描かれた闘牛場の建物。"],["1のマス","うず巻きの入り口、スタートのマス。"],["牛の頭","右上に描かれた角のある牛の頭。"],["闘牛士","左下の闘牛士の肖像。"],["説明","下段の「EXPLICACION」の文。"]]},"ambrocards":{"title":"カードをする三人の男","artist":"作者不詳（アメリカ）","date":"1865年","place":"アメリカ合衆国","game":"トランプ","medium":"アンブロタイプ","size":"14.0×11.0cm","credit":"","p":["アンブロタイプは、ガラス板に写した薄いネガの裏を黒くして、ポジのように見せる写真です。ダゲレオタイプより安く、1850〜60年代のアメリカで広く使われました。この一枚は金色の枠をつけ、赤いビロードを張ったケースに納められています。","無地の背景の前で、三人の男が小さなテーブルを囲み、手に札を持っています。左の男は山高帽、右の男はキャップをかぶり、二人とも葉巻をくわえています。中央の男は黒い上着姿でこちらを見ています。撮影のため、勝負の途中のようにポーズをとったものと思われます。"],"spots":[["手札","テーブルの上で札を持つ手。"],["山高帽の男","左で葉巻をくわえる男。"],["中央の男","黒い上着でこちらを見る男。"],["キャップの男","右で葉巻をくわえる男。"],["金色の枠","像を囲む型押しの金色の枠。"],["ケース","赤いビロード張りのケース。"]]},"morphy":{"title":"チェスの王者ポール・モーフィー","artist":"ウィンスロー・ホーマー","date":"1859年","place":"アメリカ合衆国","game":"チェス","medium":"木口木版","size":"","credit":"","p":["下に「PAUL MORPHY, THE CHESS CHAMPION」と刷られた肖像の木口木版で、まだ若い挿絵画家だったホーマー（1836〜1910年）の絵によるものです。モーフィー（1837〜1884年）はニューオーリンズ出身のチェスの名手で、1858〜59年にヨーロッパを回って一流の指し手を次々に破り、名声を得て帰国しました。","椅子に腰かけた若いモーフィーが左手を盤の縁に置き、そばにはキングやルーク、ポーンなどの駒が立っています。帰国して話題の人となった1859年の作で、新聞か雑誌の挿絵として刷られたものと思われます。"],"spots":[["駒","盤の上に立つキング、ルーク、ポーンなど。"],["盤に置いた手","盤の縁に添えた左手。"],["モーフィーの顔","まだ二十歳過ぎの若い王者。"],["蝶ネクタイ","きちんとした身なりの襟もと。"],["ひざの手","ひざの上に置いた右手。"],["題","下の「PAUL MORPHY, THE CHESS CHAMPION」。"]]},"dutton":{"title":"シャーボーン・パークの客間のダットン家","artist":"ヨハン・ゾファニー","date":"1772年ごろ","place":"イギリス","game":"トランプ","medium":"油彩・カンヴァス","size":"101.5×127.0cm","credit":"","p":["ドイツ生まれでイギリスで活躍したゾファニー（1733〜1810年）の絵です。家族をくつろいだ姿で描く「カンバセーション・ピース」は18世紀のイギリスで生まれ、人気を集めました。グロスターシャーの屋敷シャーボーン・パークの客間が舞台です。","美術館の説明によれば、父と娘、母と息子が次の手をどう打つか、トランプの勝負に頭をひねっています。家族は身内を亡くしたばかりで、両親は正式の喪服の黒、子どもたちは軽い喪の藤色・白・灰色を着ています。"],"spots":[["カード卓","緑の布を張った卓と札。"],["父","黒い服で札を持つ父。"],["娘","白い服で札を見る娘。"],["息子","灰色の服で札を持つ息子。"],["母","黒い喪服の母。"],["暖炉","火の入った大理石の暖炉。"]]},"whist":{"title":"クリスマスの学者たち――ホイストの連合ゲーム","artist":"ジェームズ・ブレザートン（H. W. バンベリー原画と思われる）","date":"1773年","place":"イギリス","game":"ホイスト（トランプ）","medium":"エッチング","size":"26.5×39.6cm","credit":"","p":["美術館によれば、ケンブリッジ大学の学者たちを皮肉った風刺画です。左下に「H. W. バンベリー画 1772」、右下に「J. ブレザートン刻」と読める銘があり、1773年にロンドンのニュー・ボンド街の店から出版されました。壁には学者の角帽が掛かっています。","四人の紳士がトランプのホイストをしながら、互いにしかめ面をしています。ホイストは二人ずつ組んで点を競う遊びで、題の「連合ゲーム」はそのしゃれと思われます。うしろでは一人が、相手の頭の上で指を立ててからかっています。召使い二人と犬二匹もそばにいます。"],"spots":[["卓のトランプ","卓の上に出された札。"],["かつらの学者","大きなかつらをつけ、手札を胸に寄せる学者。"],["指を立てる男","うしろから相手の頭の上で指を立てる男。"],["召使いの女","帽子をかぶり、盆を持つ召使い。"],["角帽","壁に掛かった大学の角帽。"],["右の犬","右下で吠える小さな犬。"]]},"hey":{"title":"チェスをする三人の男","artist":"パウル・ハイ","date":"1877〜1952年","place":"ドイツ","game":"チェス","medium":"版画（エッチングと思われる）","size":"19.3×26.0cm","credit":"","p":["ドイツの画家・挿絵画家パウル・ハイ（1867〜1952年）の版画です。卓に寄った三人の年配の男が、一つのチェス盤をのぞき込んでいます。細い線を重ねて、深いしわや白いひげを描いています。","美術館の記録のとおり、左の男はあごに手を当て、右の男は葉巻を指にはさんで駒の上に手をのばしています。卓の左にはコーヒーカップが二つ、グラスとマッチ箱。カフェで指す一局と思われます。"],"spots":[["チェス盤","卓の上の盤と駒。"],["あごに手の男","白いひげの男。あごに手を当てて考えこみます。"],["まん中の男","身を乗り出して駒に手をのばす男。"],["右の男","うしろからのぞき込む男。"],["葉巻の手","葉巻を指にはさんだ手。"],["コーヒーとマッチ箱","左のカップ二つ、グラス、マッチ箱。"]]},"artful":{"title":"ずるい一枚、おばあちゃんには一枚多すぎ（ハートが切り札！）","artist":"作者不詳","date":"1852〜1863年","place":"イギリスと思われる","game":"カード遊び","medium":"ステレオ写真（色つき）","size":"8.4×17.4cm","credit":"","p":["英語の題は「The artful card, or, one too many for granny. Hearts are trumps!」。ずるい札でおばあちゃんを出し抜く、という笑い話のような場面を、二枚一組のステレオ写真に仕立てたものです。英語の題から、イギリスで作られたものと思われます。","丸い卓でおばあちゃんと少女がカードをし、緑の服の娘は手札を持ったまま、うしろの若い男に肩を抱かれています。「ハートが切り札」は、トランプのハートと恋心をかけたしゃれと思われます。糸車や食器棚のある部屋は、写真館の作り物でしょう。"],"spots":[["娘の手札","緑の服の娘が胸もとに持つカード。"],["若い男","うしろから娘の肩に手を置く男。"],["おばあちゃん","頭巾をかぶり、カードに目を落とす年配の女性。"],["少女","にっこり笑ってカードを出す少女。"],["卓","札や小物が置かれた丸い卓。"],["食器棚","ガラス戸に器が並ぶ棚。"]]},"cezcards":{"title":"カード遊びをする人のための習作","artist":"ポール・セザンヌ","date":"1890〜92年","place":"フランス","game":"トランプ","medium":"水彩、鉛筆・ベージュの紙","size":"36.2×48.5cm","credit":"","p":["セザンヌは1890年代、南フランスのエクスで、カード遊びをする男たちを何枚も描きました。これはその連作のための水彩の習作です。帽子をかぶり口ひげを生やした男が、机に向かって手札を見ています。","鉛筆の線の上に、青や灰色の水彩を薄く重ねて、上着のしわや体の量感をつかんでいます。右側や机の先は描きかけのまま残され、色が置かれたのは人物のまわりだけです。モデルは土地で働く人だったと言われます。"],"spots":[["男の顔","帽子の下で目を伏せ、手札を見る男。"],["手札","両手で持つカード。"],["机","鉛筆の線だけで描かれた机。"],["椅子","左の椅子の背もたれ。"],["上着","青と灰色を重ねた上着のしわ。"],["描きかけの部分","机の脚のあたりは線だけで残されています。"]]},"vuillardck":{"title":"ダムの勝負（『風景と室内』より）","artist":"エドゥアール・ヴュイヤール","date":"1899年","place":"フランス","game":"ダム（チェッカー）","medium":"多色リトグラフ・灰色がかった象牙色の紙","size":"36.9×28.5cm","credit":"","p":["フランスの画家ヴュイヤールが、画商アンブロワーズ・ヴォラールの出版で作った多色石版画集『風景と室内』の1枚目です。刷りは石版刷り師オーギュスト・クロが担当しました。","模様だらけの壁紙の部屋で、ひげの男がダムの盤に向かい、格子柄の服の女性が立ってあごに手を当て、盤をのぞいています。人も壁紙もソファも平らな色と模様に溶け合い、盤の白黒の市松だけがくっきり浮かびます。"],"spots":[["盤","白黒の市松もようのダムの盤。"],["ひげの男","盤に向かう男。"],["立つ女性","格子柄の服で、あごに手を当てる女性。"],["壁紙","うねる線で埋めつくした壁紙。"],["花柄のクッション","左下の花もようの布。"],["奥のランプ","壁ぎわの細いランプのような形。"]]},"cruikchess":{"title":"チェスの勝負","artist":"ジョージ・クルックシャンク（フレデリック・マリアット大尉の原画による）","date":"1814年","place":"イギリス","game":"チェス","medium":"手彩色エッチング","size":"23.8×34.5cm","credit":"","p":["イギリスの風刺画家クルックシャンクが、海軍士官で作家でもあったマリアットの下絵を版にした一枚で、版元はロンドンのハンナ・ハンフリーです。下に「GAME of CHESS」の題が入っています。","ろうそくの立つ机で、二人の老紳士がチェス盤に向かっています。それぞれの後ろには見物人が立ち、左の男は口に指を当てて「静かに」としぐさをし、右の男は柄つきの眼鏡で盤をのぞき込んでいます。口を出したがる見物人をからかった絵と思われます。"],"spots":[["盤","白黒の駒が並ぶチェス盤。"],["ろうそく","盤を照らす二本のろうそく。"],["「静かに」の男","口に指を当てて立つ見物人。"],["眼鏡の男","柄つき眼鏡で盤をのぞく見物人。"],["寝そべる犬","机の下で眠る犬。"],["題","下の「GAME of CHESS」。"]]},"domino98":{"title":"テーブルでドミノをする女性と子ども","artist":"作者不詳（アメリカ）","date":"1898年ごろ","place":"アメリカ合衆国","game":"ドミノ","medium":"鶏卵紙プリント（ガラスに貼り付け）","size":"40.8×51.1cm","credit":"","p":["アメリカの写真館で撮られたと思われる大判の写真で、ガラス板に貼り付けて仕上げてあります。白い服の女性と巻き毛の女の子が、花を飾った小さなテーブルをはさんで座っています。","テーブルの上にはドミノの牌が並び、女性は牌を手にして並べています。女の子はほおづえをついて、それを見つめています。カーテン、飾り棚、絵のかかった壁は、写真館の背景と思われます。"],"spots":[["ドミノの牌","テーブルに並ぶ白いドミノ。"],["女の子","ほおづえをついて牌を見る女の子。"],["女性","牌を手に並べる白い服の女性。"],["花","テーブルの花瓶に生けた花。"],["飾り棚","右奥の装飾の多い棚。"],["書き込み","右下に白く入った文字。"]]},"langkat":{"title":"船の上でカードをするアルベルト・グラーザーと友人たち（スマトラ、ランカット）","artist":"作者不詳（H. エルンスト社）","date":"1895〜1905年","place":"インドネシア（スマトラ島、ランカット）","game":"カード遊び","medium":"写真","size":"17.5×22.8cm","credit":"","p":["スマトラ島北部のランカットで撮られた写真です。右下に「H. Ernst & Co. / Bindjey Langkat」という写真館の空押し印があり、裏には、まん中の人物がアルベルト・グラーザーで、ある夫人の兄弟だと手書きされています。","日よけを張った船の甲板で、白い服の三人の男が卓を囲んでカードを手にしています。卓の上には札と小さなコインのようなものが置かれ、右の男のそばには瓶があります。白い服や日よけは、暑い土地での暮らしぶりを伝えています。"],"spots":[["卓の上","配られた札とコインのようなもの。"],["グラーザー","まん中で札を広げる人物。裏書きに名前があります。"],["左の男","背中を少し見せて札を持つ男。"],["右の男","ひげの男。札を手に卓につきます。"],["瓶","右の男のそばの瓶。"],["日よけ","屋根から垂れる葉の飾りと日よけ。"]]},"chatur":{"title":"チャトランガの勝負","artist":"作者不詳","date":"1805〜1815年","place":"インド","game":"チャトランガ","medium":"グワッシュ・金、筆","size":"16.2×9.8cm（画面）","credit":"","p":["インドの細密画です。美術館の記録によれば、二人の女性がチャトランガという盤の遊びをしていて、侍女がハエ払いを持っています。チャトランガはインドの古い盤の遊びで、チェスの祖先とされます。","白い柱のアーチの下、赤い敷物の上で、紺の衣の女性と橙の衣の女性が市松模様の盤をはさんで向かい合っています。橙の衣の女性は手を差し出して何か言っているようです。絵のまわりは黒と白の線で縁どった濃い赤の枠で囲まれています。"],"spots":[["盤","赤い敷物の上の市松模様の盤。"],["紺の衣の女性","金の飾りをつけ、盤に手をのばす女性。"],["橙の衣の女性","手を差し出して向かい合う女性。"],["侍女","うしろに立つ侍女。"],["ハエ払い","侍女が掲げるハエ払い。"],["赤い枠","黒と白の線で縁どった濃い赤の枠。"]]},"shabbarat":{"title":"女性の間の夜","artist":"作者不詳","date":"1760〜1770年","place":"インド","game":"チャウパル（パチーシ）","medium":"グワッシュ・金、筆","size":"34.3×25.6cm","credit":"","p":["インドの細密画です。美術館の記録によれば、宮殿の広い中庭で四人の女性が盤の遊びをしていて、それはチャウパルまたはパチーシと呼ばれる遊びです。十字形の布の盤のまわりに女性たちが座っています。","手前右の女性は長い棒形のサイコロを三本持って、いまにも振ろうとしています。その隣でまくらにもたれているのが、いちばん身分の高い女性です。夜ですが、テラスのあちこちにランプが置かれ、遠くの町の壁にも無数の灯りがともっています。記録は、イスラームの祭り、シャベ・バラートを祝っているのだろうとしています。"],"spots":[["十字形の盤","床に広げた十字形の盤。"],["サイコロを持つ女性","棒形のサイコロを手にした手前の女性。"],["まくらにもたれる女性","いちばん身分の高い女性。"],["侍女","盆を持って近づく女性。"],["ランプ","ガラスの覆いの中で灯るろうそく。"],["遠くのあずまや","噴水のある庭とあずまや、町の灯り。"]]},"govase":{"title":"碁を打つ女性たちを描いた卵形の花瓶","artist":"作者不詳（「唐金堂」の印）","date":"1724年","place":"中国（広東）","game":"囲碁","medium":"磁器、上絵付け（粉彩）・金彩","size":"高さ15.3cm","credit":"","p":["ごく薄い磁器に色絵で描いた中国の花瓶です。裏側には「甲辰の年の花朝の日（花の祭りの日）に、嶺南の珠江のほとりの居心地のよい家で描いた、碁の一局の図」という銘と、「唐金堂」の赤い印があります。ハーグの収集家ロワイエの磁器コレクションの一点です。","二人の女性が卓の碁盤をはさみ、左の女性は碁石の器を手にしています。右では女性二人と子ども二人が勝負をのぞき込みます。うしろの台には、孔雀の羽をさした花瓶やサンゴなどの骨董が並びます。"],"spots":[["碁盤","卓に置いた碁盤と白黒の石。"],["左の打ち手","碁石の器を持ち、指を差す女性。"],["右の打ち手","盤に身を乗り出す女性。"],["見物の女性たち","うしろから盤をのぞき込む女性たち。"],["孔雀の羽とサンゴ","台の花瓶にさした孔雀の羽とサンゴ。"],["碁石の器","左の女性が持つ石入れ。"]]},"yokihi":{"title":"玄宗と楊貴妃の双六","artist":"作者不詳（摺物）","date":"1822年","place":"日本","game":"盤双六","medium":"多色摺木版、金属顔料","size":"21.6×19.1cm","credit":"","p":["摺物（すりもの）は、絵に狂歌などを添え、厚い紙や金属の粉を使って贅沢に刷った版画で、歌人たちが仲間への贈り物として作らせました。この一枚には狂歌が一首と、歌人の名「橘五園」が刷られています。","美術館の記録によれば、唐の玄宗皇帝（685〜762年）が愛した楊貴妃（719〜756年）と双六をしている場面で、遊びは盤双六、バックギャモンやトリックトラックの仲間です。赤い台にのせた箱形の盤に、白黒の駒が並んでいます。"],"spots":[["盤","赤い台にのせた箱形の双六盤と駒。"],["楊貴妃","髪に花飾りをつけ、盤に手を置く楊貴妃。"],["玄宗","あごに手をやり盤を見る玄宗。"],["狂歌","左上に刷られた一首と歌人の名。"],["屏風","うしろの、山を描いた屏風。"],["署名と印","右下の署名と朱印。"]]},"disderi":{"title":"船乗りの衣装でカードをする男たち","artist":"ディスデリ社","date":"1850〜1890年","place":"フランス（パリ）","game":"カード遊び","medium":"鶏卵紙プリント（名刺判写真）","size":"8.6×5.3cm","credit":"","p":["裏にパリの「ディスデリ社（イタリアン大通り8番地）」の刷り込みがある名刺判の写真で、アルバムに貼られていました。ディスデリは、小さな写真を名刺のように何枚も刷る「カルト・ド・ヴィジット」を広めた写真家です。","三角帽に長い上着、白い靴下という昔ふうの装いの男たちが、模様のある卓を囲んでカードをしています。美術館の記録は「船乗りの衣装」としていますが、芝居か仮装のための衣装と思われます。まん中の男は立ち上がって卓をのぞき込んでいます。"],"spots":[["卓","模様の縁取りのある卓。札や杯が見えます。"],["立ち上がる男","三角帽をかぶり、卓をのぞき込む男。"],["左の男","札を手に座る男。"],["右の男","三角帽をかぶり、札を手にする男。"],["留め金の靴","白い靴下に留め金の靴。"],["金の枠","写真を囲む台紙の金色の枠。"]]},"gans":{"title":"がちょう盤（74マスの渦巻き）","artist":"ヤン・オールトマン（父）、原案 ダニエル・ウィレム・ストーペンダール","date":"1763〜1823年","place":"オランダ","game":"ガチョウ遊び（すごろく）","medium":"木版（青・赤・緑で彩色）","size":"40.8×46.8cm","credit":"","p":["オランダで刷られた、渦巻きのすごろく盤です。美術館によれば、マスは1から74まで並び、いくつかのマスに絵が入っています。版を作ったのはヤン・オールトマン、図案はストーペンダールで、右下に「invenit（考案）」と名があります。","ゴールの74は、まん中の、夕日の沈む海辺に立つ神殿です。マスには「LEER GELD（授業料）」「DWAALWEG（迷い道）」「DOMHEID / WYSHEID（愚かさ／知恵）」などの言葉や、大鎌を持つガイコツの「EINDE（終わり）」があり、人生の道を教える教訓のすごろくと思われます。"],"spots":[["74：神殿","ゴールの神殿。夕日の沈む海辺に立っています。"],["1：スタート","左下の最初のマス。"],["授業料","「LEER GELD」のマス。ここに止まると払うものと思われます。"],["迷い道","「DWAALWEG」と書かれた森の道。"],["終わり","大鎌を持つガイコツの「EINDE」。"],["サイコロ","二つのサイコロが描かれたマス。"]]},"merelle":{"title":"メレルと凧あげ","artist":"クローディーヌ・ステラ（ジャック・ステラの原画による）","date":"1657年","place":"フランス（パリ）","game":"メレル（ナイン・メンズ・モリス）","medium":"エングレーヴィング","size":"11.7×14.1cm","credit":"","p":["画家ジャック・ステラの図案を、姪のクローディーヌが版に刻んだ、子どもの遊びの連作の17番です。美術館によれば、51枚の版画を綴じたアルバムの一枚です。遊んでいるのは、ふくよかな裸の子ども（プット）たちです。","左手前では、石の台に線を引いた盤で「メレル（ナイン・メンズ・モリス）」を遊んでいます。右の地面には四角を描いた「フラン・デュ・カロー（床の四角に硬貨を投げる遊び）」の線、奥では一人が凧を揚げて走ります。下の詩は、どの遊びにもみな一生懸命と歌っています。"],"spots":[["メレルの盤","石の台に刻んだ盤と、置かれた駒。"],["凧","空に揚がる凧。"],["凧を揚げる子","糸を引いて走る子。"],["フラン・デュ・カロー","地面に引いた四角と対角線。"],["指さす子","何かを手に、地面の線を指す子。"],["題","「LA MERELLE, & LE CERF VOLANT」の文字。"]]},"feldcards":{"title":"庭の卓でカードをする人々（立体写真）","artist":"作者不詳","date":"1850〜1880年","place":"不明（裏にグローニンゲンの店の印）","game":"カード遊び","medium":"鶏卵紙プリント（ステレオ写真）","size":"8.5×17.0cm","credit":"","p":["格子垣にツタのはう庭で、家族か仲間らしい人たちが卓を囲んでカードをしているステレオ写真です。裏にはオランダ・グローニンゲンの「フェルトブリュッヘ社」の印が押されています。売った店か版元の印と思われます。","左のひげの男は札を高く振り上げ、いまにも卓へたたきつけそうです。ほおづえをついた男、札を持つ少年、白髪の老人、うしろから見守る女性と、勝負の一瞬を写しています。長く動かずにいる必要があったので、ポーズをつけた場面と思われます。"],"spots":[["振り上げた札","ひげの男が高く掲げた一枚。"],["卓の上","場に出された札。"],["少年の手札","背中を向けた少年が持つ札。"],["白髪の老人","右に座る年配の男。"],["見守る女性","うしろに立って勝負を見る女性。"],["刺しゅうの椅子","手前の、花模様の布を張った椅子。"]]},"tempel":{"title":"すごろく盤「幸運の神殿」","artist":"作者不詳","date":"1816年","place":"オランダ","game":"すごろく（サイコロの遊び）","medium":"木版、活版の文字","size":"43.0×48.5cm","credit":"","p":["1から74までのマスがうず巻きに並ぶ、遊び用の一枚刷りです。中央には海辺に立つ円い神殿が描かれ、同じコレクションに残る遊び方の紙では「幸運の神殿」と呼ばれ、「投げる遊び」つまりサイコロの遊びとされています。","マスの多くは空いた丸ですが、ところどころにバラ、いばら、サイコロ、鉄の門、渡し船などの絵や、「LEER GELD（授業料）」「DOMHEID（愚かさ）」「WYSHEID（賢さ）」の文字が入っています。良い行いと悪い行いを通って神殿をめざす、教えをこめたすごろくと思われます。"],"spots":[["幸運の神殿","中央の海辺の神殿。74のゴールです。"],["1のマス","左下から始まるスタート。"],["授業料","「LEER GELD」と書かれたマス。"],["サイコロ","上の段に描かれた二つのサイコロ。"],["渡し船","下の段の「OVER HAAL（渡し）」の絵。"],["愚かさと賢さ","右の「DOMHEID」「WYSHEID」の文字。"]]},"verkeer":{"title":"小さな盤（フェルケールの盤）","artist":"作者不詳","date":"1690〜1710年","place":"オランダ（アムステルダム）","game":"フェルケール（バックギャモンの仲間）、チェス、ナイン・メンズ・モリス","medium":"クルミ材、オリーブ材・黒檀・ツゲ・骨の象嵌、銅の金具","size":"閉じて5.8×5.8cm（開いて11.6cm）","credit":"","p":["一辺わずか6センチほどの、箱のように開く遊び盤です。外側にはチェス盤とナイン・メンズ・モリス（ミューレ）の盤、内側にはフェルケール（オランダのバックギャモンの仲間）の盤があり、銅の蝶番と小さなかぎで閉じます。","中にはサイコロ1個、骨の駒9個、黒檀の駒4個、小さな硬貨3枚が残っています。美術館の番号から、ペトロネラ・オールトマンの人形の家の調度のひとつと思われます。小さくても木の象嵌はていねいで、本物の盤と同じ作りです。"],"spots":[["サイコロ","米粒ほどの小さなサイコロ。"],["骨の駒","白い骨の円い駒。"],["黒檀の駒","黒い黒檀の駒。"],["三角の目","明るい木と暗い木を交互に象嵌した三角。"],["蝶番","二つ折りにする銅の蝶番。"],["かぎ","閉じるための小さな銅のかぎ。"]]},"silverbd":{"title":"銀の小さな盤と駒","artist":"フレデリック・ファン・ストラント2世","date":"1739年","place":"オランダ（アムステルダム）","game":"ダム（チェッカー）、ナイン・メンズ・モリス","medium":"銀","size":"5.4×5.4cm","credit":"","p":["縦横5.4センチの銀の盤で、64マスの盤に縁を立て、つり下げ用の輪をつけています。黒にあたるマスには細かい線が彫られ、裏にはナイン・メンズ・モリス（ミューレ）の線が彫られています。","アムステルダムの町の印、1739年を示す年記号「E」、銀細工師フレデリック・ファン・ストラント2世の印が打たれています。いっしょに15個のダムの駒が残り、8個には花、7個には円の模様があります。人形の家や飾り棚に置く、銀の小さな道具と思われます。"],"spots":[["花模様の駒","花の模様を打ち出した駒。"],["円模様の駒","円の模様の駒。"],["つり輪","盤の角についた輪。"],["彫りのマス","細かい線を彫った暗いマス。"],["平らなマス","磨いたままの明るいマス。"],["縁","盤のまわりに立ち上がる縁。"]]},"schaak1550":{"title":"騎馬の駒のチェスセット","artist":"作者不詳","date":"1550年","place":"ドイツ","game":"チェス","medium":"ツゲ、針葉樹材","size":"最大の駒 高さ10.5cm","credit":"","p":["どの駒も、回し削りの台座に花模様の柵をめぐらせ、その上に人や馬を彫り込んだチェスの駒です。王や女王は馬やラバに乗り、狩りに出かける姿で表されています。","美術館の記録によれば、黒の王は竜を踏む後ろ足立ちの馬に乗り、首には金羊毛騎士団を思わせる鎖をかけていて、カール5世ではないかとされています。女王は鷹を手に乗せてラバにまたがります。右端にはサルが人の背に乗る、おどけた駒もあります。"],"spots":[["王","冠をかぶり、ひげをたくわえた馬上の王。"],["女王","鷹を手に、横座りでラバに乗る女王。"],["サルの駒","人の背に乗るサル。"],["おどけた駒","人が人の背に乗る、左端の駒。"],["足もとの生きもの","馬の足もとにうずくまる竜や動物。"],["台座","花模様の柵をめぐらせた回し削りの台座。"]]},"kraaij":{"title":"居間で盤の遊びをする男女","artist":"作者不詳","date":"1900〜1910年","place":"オランダと思われる","game":"バックギャモン","medium":"日光現像のコロジオン銀塩プリント","size":"8.0×11.1cm","credit":"","p":["ワイン商「クライ社（ボルドー・アムステルダム）」の写真などを収めた、ある家族のアルバムの一枚です。シャンデリアの下がる居間で、家族や知り合いらしい男女がテーブルを囲んでいます。","テーブルの上には二つ折りの箱形の盤が開かれ、左右の女性がそれぞれサイコロ筒を手にしています。美術館の記録は「盤の遊び」ですが、箱の盤と筒からバックギャモンと思われます。そばにはコーヒー茶碗、奥には鳥かごが見え、くつろいだ家の夜の様子が伝わります。"],"spots":[["箱の盤","二つ折りの箱を開いた盤。"],["左のサイコロ筒","眼鏡の女性が持つ筒。"],["右のサイコロ筒","水玉の服の女性が振ろうとする筒。"],["鳥かご","奥の台に置かれた鳥かご。"],["シャンデリア","天井から下がるガラスの火屋の明かり。"],["立つ男","右に立って勝負を見下ろす男。"]]},"braekel":{"title":"ダムをする老夫婦","artist":"フェルディナント・デ・ブラーケレール（父）","date":"1862年","place":"ベルギー（アントワープ）","game":"ダム（チェッカー）","medium":"エッチング","size":"21.8×16.5cm","credit":"","p":["アントワープの画家デ・ブラーケレール（1792〜1883年）のエッチングで、左下に「Ferdinand De Braekeleer Antwerpen 1862」と署名があります。暖炉のある古い台所で、年老いた男と女が小さな卓をはさんでいます。","卓の上の盤には丸い駒が並び、男は駒をつまみ、女は手を広げて何か言い返しているようです。床には帽子が置かれ、駒もいくつか落ちています。棚には皿が並び、窓の外には家並みが見えます。"],"spots":[["盤と駒","卓に置いた盤と丸い駒。"],["老人","かがみ込んで駒をつまむ男。"],["老婆","頭巾をかぶり、手を広げて話す女。"],["床の帽子","床に置かれた男の帽子。"],["署名","「Ferdinand De Braekeleer Antwerpen 1862」。"],["棚の皿","暖炉の上の棚に並ぶ大皿。"]]},"billiard":{"title":"ビリヤード","artist":"H. W. バンベリーの原画による（作者不詳）","date":"1780年","place":"イギリス（ロンドン）","game":"ビリヤード","medium":"エッチングと点刻","size":"30.0×39.1cm","credit":"","p":["イギリスの風刺画家ヘンリー・ウィリアム・バンベリーの原画による版画で、1780年にロンドンのワトソン＆ディキンソンの店から出版されました。美術館によれば、連作の4番目です。","二人の男がビリヤードをし、まわりの男たちが息をのんで見守っています。手前の男は台に身を乗り出してキューを構え、別の男はキューを肩にかついでいます。壁にはキュー立てと、点数を数える丸い文字盤が並びます。美術館は台が三角形に見えると記しています。"],"spots":[["台と球","布張りの台と、その上の球。"],["構える男","台に身を乗り出してキューを突き出す男。"],["キューをかつぐ男","長いキューを持って待つ男。"],["点数の文字盤","壁の丸い二つの盤。点数を数える道具と思われます。"],["キュー立て","壁に立てかけた何本ものキュー。"],["笑う二人","右で顔を寄せて笑う見物人。"]]},"baizi":{"title":"百子図（部分）","artist":"徐揚宏","date":"18世紀","place":"中国","game":"囲碁","medium":"巻物、紙本墨画（淡彩）","size":"29.8×526cm（全体）","credit":"","p":["中国の職業画家、徐揚宏による長さ5メートルを超える巻物から、碁の場面を切り出しました。庭で百人の子どもたちが遊び、楽を奏で、本を読み、字を書いています。「百子」はアジアの美術で大切な題材で、子だくさんと家の繁栄を表します。","この巻物は、のちに日本の谷文晁が写したことでも知られ、写しも同じ美術館にあります。芭蕉と太湖石のそばで、子どもたちが低い台の碁盤を囲み、二人が碁石の器を手に打ち合い、まわりの子がのぞき込んでいます。"],"spots":[["碁盤","低い台にのせた碁盤と石。"],["石を打つ子","青い上着で、碁石の器に手を入れる子。"],["もう一人の打ち手","盤に身を乗り出す白い衣の子。"],["頭に手をやる子","うしろで頭をかかえるように見る子。"],["太湖石","穴のあいた大きな奇石。"],["羽うちわの子","左で羽うちわを持つ子。"]]},"schenkcards":{"title":"トランプをする二人の中国の女性","artist":"ピーテル・スヘンク（子）","date":"1727〜1775年","place":"オランダ（題材は中国）","game":"トランプ","medium":"エッチング","size":"16.5×26.2cm","credit":"","p":["アムステルダムの版元・版画家ピーテル・スヘンク（子）が出した、中国風の人物や風景を集めた版画集『新しく考案された中国人たち』第一部の一枚です。ヨーロッパで流行した「シノワズリ（中国趣味）」の版画で、中国を想像して描いたものです。","美術館の記録によれば、庭で二人の中国の女性がカード遊びをしていて、右から盆に食べ物を盛った女性が来ます。卓の上の札はヨーロッパのトランプのように見えます。左の台の上ではウサギが休み、川には帆船が浮かんでいます。"],"spots":[["卓の札","卓に広げたカード。ヨーロッパの札のように見えます。"],["左の女性","札を手に相手を見る女性。"],["右の女性","札を卓に置く女性。"],["盆を持つ女性","食べ物を盛った盆を運ぶ女性。"],["ウサギ","左の台の上で休むウサギ。"],["帆船","川に浮かぶ帆船。"]]},"gosaucer":{"title":"碁を打つ人々を描いた皿","artist":"作者不詳","date":"1725〜1735年","place":"中国","game":"囲碁","medium":"磁器、上絵付け（粉彩）・金彩","size":"径16.4cm","credit":"","p":["粉彩と呼ばれる柔らかな色の上絵で描いた中国の皿です。裏には、筆・如意・墨を二重の円で囲んだ印が描かれています。美術館の記録には「男と女が碁を打つ」とも「三人の女性のうち二人が碁を打つ」ともあり、人物の見方が分かれています。","部屋の中の卓に碁盤が置かれ、二人が向かい合って石を打ち、もう一人がうしろから立って見ています。卓には黄色い碁石入れ、うしろには花を生けた花瓶をのせた台、右には大きな青い壺が描かれています。"],"spots":[["碁盤","卓に置かれた碁盤と石。"],["左の打ち手","薄紫の衣で卓に寄りかかる人。"],["右の打ち手","盤に石を打つ桃色の衣の人。"],["見物の人","うしろから立って見る人。"],["花瓶","台にのせた花入れ。"],["青い壺","右の大きな壺。"]]},"cheetham":{"title":"ちょっとしたカードの集まり（ロシアにて）","artist":"作者不詳","date":"1903〜1904年","place":"ロシア","game":"カード遊び","medium":"日光現像のゼラチン銀塩プリント","size":"9.2×11.5cm","credit":"","p":["ロシアに住んだイギリスのチーザム家のアルバムにある写真で、台紙に英語で「a little card-party（ちょっとしたカードの集まり）」と書き込まれています。美術館は、写っているのはジョゼフ・チーザムを訪ねたイギリスの友人たちだろうと記しています。","壁紙の部屋で、花模様のテーブル掛けをかけた卓を三人が囲み、手札を広げています。ろうそく立てが二本立ち、まん中の女性は札を扇のように開いて笑っています。遠い土地で同郷の友と過ごす、気楽なひとときと思われます。"],"spots":[["左の男の手札","ひげの男が広げる札。"],["女性の手札","まん中の女性が扇のように開いた札。"],["右の男","身を乗り出して札を持つ男。"],["ろうそく立て","卓に立つ二本のろうそく立て。"],["テーブル掛け","花と模様の大きなテーブル掛け。"],["書き込み","台紙の「a little card-party」。"]]},"problem":{"title":"難問（チェスをする男女・立体写真）","artist":"作者不詳","date":"1852〜1863年","place":"不明","game":"チェス","medium":"ステレオ写真（色つき）","size":"8.4×17.4cm","credit":"","p":["英語の題は「The Problem（難問）」。白いかつらと18世紀ふうの衣装の二人が、飾り脚の卓でチェスをしている場面を、色をつけた二枚一組のステレオ写真にしたものです。裏には「Simons」と手書きされています。","若い方は両手でほおをかかえて盤を見つめ、向かいの年配の男はにやりと笑っています。どちらが難問を抱えているかが一目でわかる、芝居のような場面と思われます。足もとには犬が寝そべっています。"],"spots":[["盤と駒","飾り脚の卓の上の盤と駒。"],["考えこむ人","両手でほおをかかえて盤を見つめる人。"],["笑う男","青い上着でにやりと笑う年配の男。"],["犬","足もとに寝そべる犬。"],["赤いカーテン","色をつけた背景のカーテン。"],["もう一枚","右の写真。立体鏡で奥行きが出ます。"]]},"tarocco":{"title":"タロットの10枚のカード","artist":"作者不詳（ジュゼッペ・マリア・ミテッリの図案と思われる）","date":"1660〜1718年","place":"イタリア（ボローニャ）","game":"タロッキ（タロットのカード遊び）","medium":"エッチングとエングレーヴィング、一部を薄茶で手彩色","size":"台紙に貼られた10枚","credit":"","p":["ボローニャで作られたタロットの一組から、10枚のカードを台紙に並べて貼ったものです。タロットはもとは占いではなく、切り札のあるカード遊びに使われました。上の段の左端は表題のカードで、美術館は画家ミテッリの肖像かもしれないとしています。","上の段には冠をかぶった人や馬に乗った人など4人の人物、下の段には「金貨」のスートの6から10が並び、数だけ金貨の模様が刷られています。版画で刷った線に、薄い茶色で一部に色がつけられています。"],"spots":[["表題のカード","左上、肖像の入った額と銘文のカード。"],["冠の男","笏を持つ、冠をかぶった人物。"],["立つ女性","冠をかぶり、手に杯を持つ女性。"],["馬上の人","馬にまたがる人物のカード。"],["金貨の10","下の段の左、10枚の金貨。"],["金貨の6","下の段の右、6枚の金貨。"]]},"kindtegel":{"title":"子どもの遊びのタイル","artist":"作者不詳","date":"1680〜1730年","place":"オランダ","game":"子どもの遊び（竹馬、ぶらんこなど）","medium":"錫釉陶器（デルフト焼のタイル）、青の絵付け","size":"107×80cm（48枚）","credit":"","p":["縦8枚、横6枚、あわせて48枚のタイルをひと続きに並べたものです。どのタイルにも、遊ぶ二人の子どもが青い絵の具で小さく描かれ、四隅には「クモ」と呼ばれる小さな飾りがついています。","竹馬に乗る子、ぶらんこを押してもらう子、地面にしゃがんで何かで遊ぶ子など、一枚ごとに違う遊びが描かれています。こうした「子どもの遊び」のタイルはオランダで好まれ、台所や暖炉のまわりの壁に張られたと思われます。"],"spots":[["竹馬","竹馬に乗る子ども。"],["ぶらんこ","ぶらんこを押してもらう子ども。"],["地面の遊び","しゃがんで何かを並べて遊ぶ子ども。"],["クモの飾り","タイルの四隅の小さな飾り。"],["48枚の並び","縦8枚、横6枚のタイル。"],["右下の一枚","右下の角のタイル。"]]},"dammolen":{"title":"ダムとミューレの小さな盤","artist":"作者不詳","date":"1740〜1760年","place":"オランダ（アムステルダム）","game":"ダム（チェッカー）、ナイン・メンズ・モリス","medium":"クルミ材、明るい色の詰め物","size":"4.2×4.0×1.5cm","credit":"","p":["横4センチほどの、クルミ材の小さな盤です。ほぼ正方形で縁が立ち上がり、片面はダムの盤、もう片面はミューレ（ナイン・メンズ・モリス）の盤として使えます。","ダムの面はマスを彫り込んで明るい色の詰め物を埋め、木の地の色との市松にしています。ミューレの面の線も彫って同じ詰め物で埋めてあります。これほど小さいので、人形の家のための品と思われます。"],"spots":[["市松のマス","彫って明るい詰め物を埋めたマス。"],["木の地のマス","クルミの地をそのまま残したマス。"],["縁","まわりに立ち上がる縁。"],["手前の角","盤の手前の角。"],["厚み","高さ1.5センチの盤の側面。"],["奥の列","いちばん奥のマスの並び。"]]},"karelpiece":{"title":"カール大帝の肖像のダムの駒（片面）","artist":"作者不詳","date":"1525〜1575年","place":"ドイツ（ニュルンベルク）","game":"ダム（チェッカー）またはトリックトラック","medium":"ツゲ材","size":"直径5.3cm","credit":"","p":["ツゲの木を彫ったダムの駒の片面です。中央に月桂冠に囲まれた横顔があり、まわりに「CAROLVS. MAGNVS. IMPER. AVGVST.（カール大帝、皇帝）」と刻まれています。","美術館には同じ作りの駒が十数個あり、ティベリウス、アグリッピナ、ルートヴィヒ敬虔帝、オットー大帝など、古代ローマから中世までの皇帝や皇后が一人ずつ彫られています。歴代の君主を一組の駒にした、ぜいたくな遊び道具と思われます。"],"spots":[["横顔","月桂冠に囲まれたカール大帝の横顔。"],["月桂冠","肖像を囲む月桂樹の輪。"],["CAROLVS","上の「CAROLVS. MAGNVS」の文字。"],["AVGVST","左の「IMPER. AVGVST」の文字。"],["星","銘文の区切りの小さな星。"],["縁","駒のふちの段。"]]},"vdberge":{"title":"オランダの遊び、楽しき暮らし！（カード遊び）","artist":"ピーテル・ファン・デン・ベルヘ（図案・刊行）","date":"1694〜1737年","place":"オランダ（アムステルダム）","game":"カード遊び","medium":"エッチング（赤・青・緑のア・ラ・プペ刷り）","size":"27.3×17.0cm","credit":"","p":["アムステルダムの版画家・版元ファン・デン・ベルヘの風刺画で、題は「LE JEU HOLLANDOIS. LA BELLE VIE!」。美術館によれば、居酒屋で男たちがカードをしていて、グラスを掲げてため息をつく男のそばや卓の下で、悪魔たちが彼の金を巻き上げています。","下のオランダ語の詩で、のんきな遊び人は「犬の喧嘩に闘鶏、カードにサイコロで金が溶けた」と嘆きます。左右には二匹の悪魔がドイツ語で「愉快にやれ、サイコロとカードで」と誘う言葉。奥の絵にも犬の喧嘩と闘鶏が描かれています。"],"spots":[["グラスを掲げる男","大きなかつらでグラスを掲げる遊び人。"],["手札","男が手に広げたカード。"],["左の悪魔","男のうしろで笑う悪魔。"],["卓の下の悪魔","床にこぼれた硬貨をかき集める悪魔。"],["犬と闘鶏の絵","壁の絵。犬の喧嘩と闘鶏が描かれています。"],["題と詩","「LE JEU HOLLANDOIS」と、遊び人の嘆きの詩。"]]},"crespi":{"title":"サイコロ遊びをする子どもたち","artist":"ジュゼッペ・マリア・クレスピ","date":"1675〜1747年","place":"イタリア","game":"サイコロ","medium":"エッチング","size":"22.5×15.1cm","credit":"","p":["ボローニャの画家クレスピの、自分で版を刻んだエッチングです。美術館によれば、四人の子どもが道ばたでサイコロ遊びをしています。下にはイタリア語の三行の詩が添えられています。","しゃがんだ子が地面にサイコロを転がし、三人がまわりで見ています。詩は「骨（サイコロ）と数で…短い遊び…金が減っていく」といった内容で、子どもの遊びにも賭けの戒めをこめたものと思われます。"],"spots":[["サイコロ","地面に転がる小さなサイコロ。"],["しゃがむ子","サイコロを振ったばかりの子。"],["立つ子","のぞき込むように立つ子。"],["右の子","地面に座って見守る子。"],["うしろの子","二人のうしろから顔を出す子。"],["詩","イタリア語の三行の詩。"]]}};
